head.b:skin:
/* =========================================================================
   UBAH WARNA & VARIABEL TEMA DI SINI
   ========================================================================= */
:root {
  --kv-bg: #F6F7FB;
  --kv-surface: #FFFFFF;
  --kv-surface-2: #F0F2F8;
  --kv-border: #E5E8F0;
  --kv-text: #20243A;
  --kv-text-muted: #737B91;
  --kv-accent: #6558D9;       /* Ubah warna aksen utama di sini */
  --kv-accent-hover: #5447C5;
  --kv-neon: #38A99B;
  --kv-success: #16A34A;
  --kv-warning: #D97706;
  --kv-danger: #DC2626;
  --kv-font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --kv-font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --kv-radius: 14px;
}

html.dark {
  --kv-bg: #11131B;
  --kv-surface: #191C27;
  --kv-surface-2: #222634;
  --kv-border: #2C3141;
  --kv-text: #F3F4FA;
  --kv-text-muted: #A0A7B8;
  --kv-accent: #A69AF4;       /* Ubah warna aksen dark mode di sini */
  --kv-accent-hover: #B8AEFF;
  --kv-neon: #70CFC0;
  --kv-success: #22C55E;
  --kv-warning: #F59E0B;
  --kv-danger: #EF4444;
}

*, *::before, *::after { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0;
  background: var(--kv-bg);
  color: var(--kv-text);
  font-family: var(--kv-font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button, input, select, textarea { font-family: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 2px solid var(--kv-accent);
  outline-offset: 2px;
}

.kv-mono { font-family: var(--kv-font-mono); font-variant-numeric: tabular-nums; }
.kv-container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }

/* Top Bar (3-Zone Contract) */
.kv-header {
  position: sticky; top: 0; z-index: 40;
  background: var(--kv-bg); /* Fallback untuk browser lama tanpa color-mix */
  background: color-mix(in srgb, var(--kv-bg) 88%, transparent);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--kv-border);
}
.kv-header-inner {
  display: flex; align-items: center; justify-content: space-between;
  gap: 32px; height: 64px;
}
.kv-brand {
  font-size: 1.25rem; font-weight: 800; letter-spacing: -0.02em;
  white-space: nowrap; flex-shrink: 0;
  background: linear-gradient(135deg, var(--kv-text) 30%, var(--kv-neon));
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.kv-nav { display: flex; align-items: center; gap: 24px; }
.kv-nav-link {
  font-size: 0.875rem; font-weight: 500; color: var(--kv-text-muted);
  white-space: nowrap; padding: 6px 2px; border-bottom: 2px solid transparent;
  transition: color 0.16s ease, border-color 0.16s ease;
}
.kv-nav-link:hover, .kv-nav-link.active {
  color: var(--kv-text); border-bottom-color: var(--kv-accent);
}
.kv-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 9px 18px; border-radius: 8px; font-size: 0.875rem; font-weight: 600;
  border: 1px solid transparent; cursor: pointer; white-space: nowrap;
  transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
}
.kv-btn:active { transform: scale(0.98); }
.kv-btn-primary { background: var(--kv-accent); color: #FFFFFF; }
.kv-btn-primary:hover { background: var(--kv-accent-hover); }
.kv-btn-ghost {
  background: var(--kv-surface); color: var(--kv-text); border-color: var(--kv-border);
}
.kv-btn-ghost:hover { border-color: var(--kv-accent); }
.kv-btn-danger { background: var(--kv-danger); color: #FFFFFF; }

/* Hero Featured */
.kv-hero {
  display: grid; grid-template-columns: 1.4fr 1fr; gap: 32px; align-items: stretch;
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: 14px; padding: 32px; margin-top: 28px;
}
.kv-hero-title {
  font-size: clamp(1.75rem, 3.2vw, 2.75rem); font-weight: 800; line-height: 1.15;
  margin: 10px 0 14px; text-wrap: balance;
}
.kv-meta-line {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  font-size: 0.8125rem; color: var(--kv-text-muted);
}
.kv-cover-wrap {
  position: relative; aspect-ratio: 3 / 4; border-radius: 10px; overflow: hidden;
  background: var(--kv-surface-2); border: 1px solid var(--kv-border);
}
.kv-cover-wrap img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* Grids & Cards */
.kv-section { margin-top: 44px; }
.kv-section-head {
  display: flex; align-items: baseline; justify-content: space-between; gap: 16px;
  margin-bottom: 18px;
}
.kv-section-title { font-size: 1.25rem; font-weight: 700; margin: 0; }
.kv-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px;
}
.kv-card {
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: var(--kv-radius); overflow: hidden;
  transition: transform 0.18s ease, border-color 0.18s ease;
  cursor: pointer; display: flex; flex-direction: column;
}
.kv-card:hover { transform: translateY(-3px); border-color: var(--kv-accent); }
.kv-card-body { padding: 14px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.kv-card-title { font-size: 1rem; font-weight: 700; margin: 0; line-height: 1.3; }

/* Filters & Inputs */
.kv-toolbar {
  display: flex; flex-wrap: wrap; gap: 12px; align-items: center;
  padding: 16px; background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: var(--kv-radius); margin-top: 24px;
}
.kv-input, .kv-select, .kv-textarea {
  background: var(--kv-bg); color: var(--kv-text);
  border: 1px solid var(--kv-border); border-radius: 8px;
  padding: 9px 12px; font-size: 0.875rem;
}
.kv-input { min-width: 220px; flex: 1; }
.kv-textarea { width: 100%; min-height: 90px; resize: vertical; }

/* Chapter List & Detail */
.kv-detail-grid {
  display: grid; grid-template-columns: 280px 1fr; gap: 32px; margin-top: 28px;
}
.kv-chapter-row {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 12px 16px; border-bottom: 1px solid var(--kv-border);
  cursor: pointer; transition: background-color 0.15s ease;
}
.kv-chapter-row:hover { background: var(--kv-surface-2); }

/* Reader */
.kv-reader-bar {
  position: sticky; top: 0; z-index: 50;
  background: var(--kv-surface); border-bottom: 1px solid var(--kv-border);
  padding: 10px 20px; display: flex; flex-wrap: wrap; align-items: center;
  justify-content: space-between; gap: 12px;
}
.kv-reader-progress {
  position: fixed; top: 0; left: 0; height: 3px; background: var(--kv-neon);
  z-index: 60; transition: width 0.12s linear;
}
.kv-reader-canvas {
  margin: 0 auto; padding: 20px 12px 64px; display: flex; flex-direction: column;
  align-items: center; gap: 8px;
}
.kv-reader-canvas img {
  width: 100%; height: auto; display: block; border-radius: 4px;
  background: var(--kv-surface-2);
}

/* Admin Panel */
.kv-admin-grid {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px;
  margin: 20px 0;
}
.kv-stat-box {
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: var(--kv-radius); padding: 18px;
}
.kv-stat-val { font-size: 1.75rem; font-weight: 800; margin-top: 4px; }
.kv-table-wrap {
  overflow-x: auto; background: var(--kv-surface);
  border: 1px solid var(--kv-border); border-radius: var(--kv-radius);
}
table.kv-table { width: 100%; border-collapse: collapse; font-size: 0.875rem; }
table.kv-table th, table.kv-table td {
  text-align: left; padding: 12px 14px; border-bottom: 1px solid var(--kv-border);
}
table.kv-table th { color: var(--kv-text-muted); font-weight: 600; font-size: 0.75rem; }

/* Footer */
.kv-footer {
  margin-top: 64px; border-top: 1px solid var(--kv-border);
  padding: 32px 0; color: var(--kv-text-muted); font-size: 0.875rem;
}
.kv-footer-inner {
  display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 16px;
}

/* Admin Console SaaS Premium */
.kv-admin-shell { display: flex; align-items: stretch; min-height: 100vh; }
.kv-admin-side {
  width: 248px; flex-shrink: 0; position: sticky; top: 0; height: 100vh;
  display: flex; flex-direction: column; overflow-y: auto;
  background: var(--kv-surface); border-right: 1px solid var(--kv-border);
  padding: 20px 14px;
}
.kv-admin-logo {
  font-weight: 800; font-size: 1.05rem; letter-spacing: -0.02em;
  display: flex; align-items: center; gap: 8px; padding: 4px 8px 14px;
}
.kv-admin-logo span {
  color: var(--kv-neon); font-size: 0.6875rem; font-weight: 700;
  letter-spacing: 0.09em; text-transform: uppercase;
}
.kv-admin-side-label {
  font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--kv-text-muted);
  padding: 14px 10px 6px;
}
.kv-admin-nav { display: flex; flex-direction: column; gap: 4px; }
.kv-admin-nav-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 9px 10px; border-radius: 8px; border: none; background: none;
  color: var(--kv-text-muted); font-size: 0.875rem; font-weight: 600;
  cursor: pointer; text-align: left; white-space: nowrap;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.kv-admin-nav-item:hover { background: var(--kv-surface-2); color: var(--kv-text); }
.kv-admin-nav-item.active {
  color: var(--kv-text);
  background: linear-gradient(90deg, var(--kv-surface-2), transparent);
  box-shadow: inset 2px 0 0 var(--kv-accent);
}
.kv-admin-nav-badge {
  margin-left: auto; min-width: 20px; height: 20px; padding: 0 6px;
  border-radius: 999px; background: var(--kv-danger); color: #FFFFFF;
  font-size: 0.6875rem; font-weight: 700;
  display: inline-flex; align-items: center; justify-content: center;
}
.kv-admin-side-foot {
  margin-top: auto; padding-top: 14px; border-top: 1px solid var(--kv-border);
  display: flex; flex-direction: column; gap: 10px;
}
.kv-admin-chip {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 0.75rem; color: var(--kv-text-muted); padding: 0 4px;
}
.kv-admin-chip .dot {
  width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0;
  background: var(--kv-success); box-shadow: 0 0 8px var(--kv-success);
}
.kv-admin-chip.off .dot { background: var(--kv-warning); box-shadow: 0 0 8px var(--kv-warning); }
.kv-admin-main { flex: 1; min-width: 0; max-width: 1080px; padding: 28px 32px 48px; }
.kv-admin-topbar {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 16px; flex-wrap: wrap; margin-bottom: 22px;
}
.kv-admin-title { font-size: 1.5rem; font-weight: 800; margin: 0; letter-spacing: -0.02em; }
.kv-admin-sub { color: var(--kv-text-muted); font-size: 0.875rem; margin: 4px 0 0; }
.kv-admin-top-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.kv-stat-card {
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: 14px; padding: 18px; position: relative; overflow: hidden;
}
.kv-stat-card::after {
  content: ''; position: absolute; inset: 0 0 auto 0; height: 3px;
  background: linear-gradient(90deg, var(--kv-accent), var(--kv-neon));
  opacity: 0.8;
}
.kv-stat-ico {
  width: 34px; height: 34px; border-radius: 9px; margin-bottom: 10px;
  background: var(--kv-surface-2); color: var(--kv-accent);
  display: inline-flex; align-items: center; justify-content: center;
}
.kv-stat-label { color: var(--kv-text-muted); font-size: 0.8125rem; }
.kv-qa-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.kv-qa {
  display: flex; align-items: flex-start; gap: 12px; text-align: left;
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: 12px; padding: 14px; cursor: pointer;
  transition: transform 0.15s ease, border-color 0.15s ease;
}
.kv-qa:hover { transform: translateY(-2px); border-color: var(--kv-accent); }
.kv-qa-ico {
  width: 38px; height: 38px; flex-shrink: 0; border-radius: 10px;
  display: inline-flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, var(--kv-accent), var(--kv-neon)); color: #FFFFFF;
}
.kv-qa-title { display: block; font-weight: 700; font-size: 0.875rem; }
.kv-qa-desc { display: block; color: var(--kv-text-muted); font-size: 0.75rem; margin-top: 2px; }
.kv-admin-shell .kv-stat-box { border-radius: 14px; }
.kv-admin-shell table.kv-table th {
  text-transform: uppercase; letter-spacing: 0.06em; background: var(--kv-surface-2);
}
.kv-admin-shell table.kv-table tbody tr { transition: background-color 0.12s ease; }
.kv-admin-shell table.kv-table tbody tr:hover { background: var(--kv-surface-2); }
.kv-btn-sm { padding: 6px 10px; font-size: 0.75rem; border-radius: 7px; }
.kv-btn-danger-ghost {
  background: transparent; color: var(--kv-danger); border-color: var(--kv-border);
}
.kv-btn-danger-ghost:hover { border-color: var(--kv-danger); }

.kv-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.kv-page-thumb {
  width: 44px; height: 58px; object-fit: cover; border-radius: 6px;
  border: 1px solid var(--kv-border); background: var(--kv-surface-2);
}
.kv-badge {
  display: inline-flex; align-items: center; padding: 2px 10px;
  border-radius: 999px; font-size: 0.75rem; font-weight: 600;
  border: 1px solid var(--kv-border); color: var(--kv-text-muted);
}
.kv-badge-ok { color: var(--kv-success); border-color: var(--kv-success); }
.kv-badge-pending { color: var(--kv-warning); border-color: var(--kv-warning); }
.kv-badge-reject { color: var(--kv-danger); border-color: var(--kv-danger); }
.kv-toasts {
  position: fixed; bottom: 20px; right: 20px; z-index: 100;
  display: flex; flex-direction: column; gap: 10px; max-width: 340px;
}
.kv-toast {
  padding: 12px 16px; border-radius: 10px; font-size: 0.875rem;
  background: var(--kv-surface-2); border: 1px solid var(--kv-border);
  color: var(--kv-text); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  animation: kv-toast-in 0.18s ease;
}
.kv-toast-ok { border-color: var(--kv-success); }
.kv-toast-warn { border-color: var(--kv-warning); }
.kv-toast-err { border-color: var(--kv-danger); }
@keyframes kv-toast-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}
.kv-modal {
  position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55); z-index: 90;
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
.kv-modal-box {
  background: var(--kv-surface); border: 1px solid var(--kv-border);
  border-radius: 12px; padding: 24px; max-width: 440px; width: 100%;
}

/* Polish SaaS publik: kicker, chip, glow, gradien */
.kv-kicker {
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--kv-neon); margin: 0 0 4px;
}
.kv-chip {
  display: inline-flex; align-items: center; padding: 2px 9px;
  border-radius: 999px; background: var(--kv-surface-2);
  border: 1px solid var(--kv-border); font-size: 0.6875rem;
  font-weight: 600; color: var(--kv-text-muted); white-space: nowrap;
}
.kv-chip-accent {
  color: var(--kv-neon); border-color: var(--kv-accent);
  border-color: color-mix(in srgb, var(--kv-neon) 45%, transparent);
}
.kv-hero { position: relative; overflow: hidden; }
.kv-hero::before {
  content: ''; position: absolute; top: -120px; right: -80px;
  width: 380px; height: 380px; border-radius: 50%;
  background: radial-gradient(closest-side, rgba(99, 102, 241, 0.22), transparent);
  pointer-events: none;
}
.kv-hero::after {
  content: ''; position: absolute; bottom: -140px; left: -60px;
  width: 320px; height: 320px; border-radius: 50%;
  background: radial-gradient(closest-side, rgba(34, 211, 238, 0.14), transparent);
  pointer-events: none;
}
.kv-hero .kv-cover-wrap { box-shadow: 0 0 0 1px var(--kv-border), 0 24px 60px -24px rgba(0, 0, 0, 0.55); }
.kv-card { border-radius: 14px; }
.kv-card:hover { box-shadow: 0 14px 34px -14px rgba(99, 102, 241, 0.4); }
.kv-card .kv-cover-wrap img { transition: transform 0.25s ease; }
.kv-card:hover .kv-cover-wrap img { transform: scale(1.05); }
.kv-card-title {
  display: -webkit-box; -webkit-line-clamp: 2;
  -webkit-box-orient: vertical; overflow: hidden;
}
.kv-btn-primary { background: linear-gradient(135deg, var(--kv-accent), var(--kv-neon)); }
.kv-btn-primary:hover {
  background: linear-gradient(135deg, var(--kv-accent-hover), var(--kv-neon));
  box-shadow: 0 6px 18px -6px rgba(99, 102, 241, 0.5);
}
.kv-input, .kv-textarea { border-radius: 10px; }
.kv-select { border-radius: 999px; }
.kv-input:focus, .kv-select:focus, .kv-textarea:focus {
  outline: none; border-color: var(--kv-accent);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.18);
}
.kv-chapter-row {
  border: 1px solid var(--kv-border); border-radius: 10px;
  margin-bottom: 8px; padding: 12px 16px;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}
.kv-chapter-row:last-child { margin-bottom: 0; }
.kv-chapter-row:hover { border-color: var(--kv-accent); background: var(--kv-surface-2); }
.kv-reader-progress { background: linear-gradient(90deg, var(--kv-accent), var(--kv-neon)); }
.kv-reader-bar {
  background: var(--kv-surface);
  background: color-mix(in srgb, var(--kv-surface) 86%, transparent);
  backdrop-filter: blur(12px);
}
table.kv-table th { text-transform: uppercase; letter-spacing: 0.05em; }
table.kv-table tbody tr { transition: background-color 0.12s ease; }
table.kv-table tbody tr:hover { background: var(--kv-surface-2); }
.kv-stat-box { border-radius: 14px; }
.kv-footer { background: var(--kv-surface); }
.kv-404 { text-shadow: 0 0 40px rgba(99, 102, 241, 0.55); }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--kv-border); border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: var(--kv-text-muted); }
::-webkit-scrollbar-track { background: transparent; }

/* Soft modern SaaS visual system */
html { scroll-behavior: smooth; }
body {
  min-height: 100vh;
  background:
    radial-gradient(ellipse at 50% -18%, color-mix(in srgb, var(--kv-accent) 7%, transparent), transparent 46%),
    var(--kv-bg);
  letter-spacing: -0.012em;
}
h1, h2, h3, p { text-wrap: pretty; }
.kv-container { max-width: 1280px; padding-right: 32px; padding-left: 32px; }
.kv-header {
  background: color-mix(in srgb, var(--kv-bg) 88%, transparent);
  border-bottom-color: color-mix(in srgb, var(--kv-border) 84%, transparent);
  box-shadow: 0 8px 26px -24px rgba(30, 35, 60, 0.42);
}
html.dark .kv-header { box-shadow: 0 8px 26px -24px rgba(0, 0, 0, 0.8); }
.kv-header-inner { height: 72px; }
.kv-brand {
  font-size: 1.22rem;
  letter-spacing: -0.06em;
  background: linear-gradient(110deg, var(--kv-text) 24%, var(--kv-accent) 100%);
}
.kv-brand-mark {
  width: 36px;
  height: 36px;
  flex-basis: 36px;
  border: 0;
  border-radius: 12px;
  background: linear-gradient(145deg, var(--kv-accent), var(--kv-neon));
  box-shadow: 0 7px 16px -10px var(--kv-accent);
}
.kv-nav { gap: 5px; }
.kv-nav-link {
  padding: 8px 12px;
  border: 0;
  border-radius: 10px;
  font-size: 0.84rem;
  transition: background-color 0.18s ease, color 0.18s ease;
}
.kv-nav-link:hover, .kv-nav-link.active {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-nav-login, .kv-nav-login:hover, .kv-nav-login.active {
  color: #FFFFFF !important;
  background: var(--kv-accent);
  box-shadow: 0 7px 18px -12px var(--kv-accent);
}
.kv-nav-login:hover { background: var(--kv-accent-hover); }
.kv-theme-toggle {
  width: 42px;
  height: 42px;
  flex-basis: 42px;
  border-radius: 12px;
  background: var(--kv-surface);
  border-color: var(--kv-border);
}
.kv-btn {
  min-height: 42px;
  border-radius: 11px;
  font-weight: 650;
  letter-spacing: -0.01em;
  transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}
.kv-btn-primary {
  color: #FFFFFF;
  background: var(--kv-accent);
  box-shadow: 0 7px 18px -12px var(--kv-accent);
}
.kv-btn-primary:hover {
  background: var(--kv-accent-hover);
  box-shadow: 0 10px 24px -14px var(--kv-accent);
  transform: translateY(-1px);
}
.kv-btn-ghost {
  background: var(--kv-surface);
  border-color: var(--kv-border);
}
.kv-btn-ghost:hover {
  background: var(--kv-surface-2);
  border-color: color-mix(in srgb, var(--kv-accent) 40%, var(--kv-border));
}
.kv-btn-danger-ghost { background: var(--kv-surface); }
.kv-hero {
  min-height: 410px;
  gap: clamp(28px, 5vw, 72px);
  padding: clamp(30px, 5vw, 64px);
  margin-top: 36px;
  border-radius: 26px;
  border-color: color-mix(in srgb, var(--kv-accent) 16%, var(--kv-border));
  background:
    radial-gradient(ellipse at 87% 14%, color-mix(in srgb, var(--kv-accent) 12%, transparent), transparent 38%),
    linear-gradient(135deg, var(--kv-surface) 0%, color-mix(in srgb, var(--kv-neon) 6%, var(--kv-surface)) 100%);
  box-shadow: 0 24px 70px -58px rgba(40, 45, 80, 0.42);
}
.kv-hero::before, .kv-hero::after { opacity: 0.26; }
.kv-hero-title {
  max-width: 13ch;
  font-size: clamp(2.35rem, 5vw, 4rem);
  font-weight: 800;
  letter-spacing: -0.075em;
  line-height: 1.02;
  margin: 18px 0;
}
.kv-hero .kv-cover-wrap {
  border-radius: 20px;
  box-shadow: 0 22px 50px -30px rgba(25, 30, 55, 0.55);
  transform: rotate(1deg);
}
.kv-hero:hover .kv-cover-wrap { transform: rotate(0) translateY(-3px); }
.kv-kicker { color: var(--kv-accent); letter-spacing: 0.12em; }
.kv-section { margin-top: 60px; }
.kv-section-head { margin-bottom: 22px; }
.kv-section-title { font-size: 1.45rem; letter-spacing: -0.045em; }
.kv-grid { gap: 22px; }
.kv-card {
  border-radius: 17px;
  border-color: color-mix(in srgb, var(--kv-border) 88%, transparent);
  box-shadow: 0 8px 25px -24px rgba(30, 35, 60, 0.62);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}
.kv-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--kv-accent) 46%, var(--kv-border));
  box-shadow: 0 18px 38px -28px color-mix(in srgb, var(--kv-accent) 42%, transparent);
}
.kv-card-body { padding: 16px; gap: 9px; }
.kv-card-title { font-size: 0.98rem; letter-spacing: -0.035em; }
.kv-chip {
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--kv-surface-2);
  font-size: 0.68rem;
}
.kv-chip-accent {
  color: var(--kv-accent);
  border-color: color-mix(in srgb, var(--kv-accent) 25%, var(--kv-border));
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-toolbar {
  padding: 18px;
  gap: 12px;
  border-radius: 17px;
  box-shadow: 0 10px 28px -26px rgba(30, 35, 60, 0.55);
}
.kv-input, .kv-select, .kv-textarea {
  min-height: 44px;
  border-radius: 11px;
  background: var(--kv-surface);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.kv-input::placeholder, .kv-textarea::placeholder { color: var(--kv-text-muted); opacity: 0.78; }
.kv-input:focus, .kv-select:focus, .kv-textarea:focus {
  outline: none;
  border-color: var(--kv-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--kv-accent) 15%, transparent);
}
.kv-detail-grid {
  align-items: center;
  gap: clamp(28px, 5vw, 64px);
  margin-top: 38px;
}
.kv-detail-grid > .kv-cover-wrap {
  border-radius: 21px;
  box-shadow: 0 22px 52px -32px rgba(30, 35, 60, 0.55);
}
.kv-detail-grid h1 { letter-spacing: -0.065em; line-height: 1.08; }
.kv-chapter-row {
  min-height: 58px;
  border: 1px solid var(--kv-border);
  border-radius: 13px;
  margin-bottom: 9px;
  padding: 13px 16px;
  background: var(--kv-surface);
  transition: border-color 0.16s ease, background-color 0.16s ease, transform 0.16s ease;
}
.kv-chapter-row:last-child { margin-bottom: 0; }
.kv-chapter-row:hover {
  border-color: color-mix(in srgb, var(--kv-accent) 42%, var(--kv-border));
  background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface));
  transform: translateY(-1px);
}
.kv-stat-box, .kv-table-wrap {
  border-radius: 16px;
  border-color: var(--kv-border);
  box-shadow: 0 10px 30px -27px rgba(30, 35, 60, 0.52);
}
.kv-table-wrap { overflow-x: auto; }
table.kv-table { border-spacing: 0; }
table.kv-table th {
  color: var(--kv-text-muted);
  background: var(--kv-surface-2);
  font-size: 0.7rem;
  letter-spacing: 0.075em;
}
table.kv-table td { vertical-align: middle; }
table.kv-table tbody tr:last-child td { border-bottom: 0; }
table.kv-table tbody tr:hover { background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface)); }
.kv-footer {
  margin-top: 88px;
  background: color-mix(in srgb, var(--kv-surface) 80%, transparent);
  border-top-color: var(--kv-border);
}
.kv-footer a { transition: color 0.15s ease; }
.kv-footer a:hover { color: var(--kv-accent); }
.kv-admin-shell { background: var(--kv-bg); }
.kv-admin-side {
  width: 260px;
  padding: 24px 16px;
  background: var(--kv-surface);
  border-right-color: var(--kv-border);
}
.kv-admin-logo { padding: 5px 10px 20px; font-size: 1.12rem; }
.kv-admin-logo span { color: var(--kv-accent); }
.kv-admin-side-label { letter-spacing: 0.09em; }
.kv-admin-nav { gap: 5px; }
.kv-admin-nav-item {
  min-height: 42px;
  border-radius: 11px;
  transition: color 0.16s ease, background-color 0.16s ease;
}
.kv-admin-nav-item.active {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
  box-shadow: inset 3px 0 0 var(--kv-accent);
}
.kv-admin-chip .dot { box-shadow: none; }
.kv-admin-main { max-width: 1240px; padding: 34px clamp(22px, 4vw, 52px) 56px; }
.kv-admin-title { font-size: clamp(1.5rem, 2.5vw, 2rem); letter-spacing: -0.055em; }
.kv-admin-topbar { margin-bottom: 28px; }
.kv-admin-grid { gap: 18px; margin: 24px 0; }
.kv-stat-card {
  min-height: 136px;
  padding: 22px;
  border-radius: 17px;
  box-shadow: 0 10px 28px -26px rgba(30, 35, 60, 0.58);
}
.kv-stat-card::after { height: 2px; opacity: 0.4; }
.kv-stat-ico {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-stat-val { letter-spacing: -0.06em; }
.kv-qa-grid { gap: 14px; }
.kv-qa {
  min-height: 90px;
  padding: 17px;
  border-radius: 15px;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}
.kv-qa:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--kv-accent) 36%, var(--kv-border));
  box-shadow: 0 14px 28px -24px color-mix(in srgb, var(--kv-accent) 40%, transparent);
}
.kv-qa-ico {
  border-radius: 12px;
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 10%, var(--kv-surface));
}
.kv-admin-shell .kv-stat-box { border-radius: 17px; }
.kv-admin-shell .kv-toolbar { margin-top: 0; }
.kv-admin-shell table.kv-table th { background: var(--kv-surface-2); }
.kv-form-grid { gap: 16px; }
.kv-form-grid > label, .kv-admin-main label { color: var(--kv-text); font-weight: 600; }
.kv-form-grid .kv-input, .kv-form-grid .kv-select, .kv-form-grid .kv-textarea { margin-top: 7px !important; }
.kv-page-thumb { border-radius: 9px; }
.kv-badge-ok, .kv-badge-pending, .kv-badge-reject {
  border-width: 1px;
  background: color-mix(in srgb, currentColor 8%, var(--kv-surface));
}
.kv-modal { background: rgba(25, 29, 45, 0.42); backdrop-filter: blur(5px); }
.kv-modal-box {
  padding: 28px;
  border-radius: 19px;
  box-shadow: 0 28px 80px -32px rgba(25, 30, 55, 0.45);
}
.kv-toasts { z-index: 100; }
.kv-toast {
  border-radius: 13px;
  box-shadow: 0 12px 30px -20px rgba(25, 30, 55, 0.5);
}
.kv-reader-app { --kv-reader-bg: #171923; }
.kv-reader-app[data-theme="light"] { --kv-reader-bg: #F4F5F9; }
.kv-reader-app[data-theme="sepia"] { --kv-reader-bg: #F2EBDD; }
.kv-reader-header { box-shadow: 0 10px 28px -26px rgba(0, 0, 0, 0.5); }
.kv-reader-back, .kv-reader-chapter-link { border-radius: 11px; }
.kv-reader-chapter-link.next {
  color: #FFFFFF;
  background: var(--kv-accent);
}
.kv-reader-chapter-link.next:hover { background: var(--kv-accent-hover); filter: none; }
.kv-reader-tools .kv-btn-ghost, .kv-reader-tools .kv-select,
.kv-reader-page-controls .kv-btn-ghost {
  border-radius: 10px;
}
.kv-reader-canvas { gap: 10px; }
.kv-reader-canvas img {
  border-radius: 5px;
  box-shadow: 0 12px 35px -22px rgba(0, 0, 0, 0.55);
}
.kv-reader-end-nav {
  border-radius: 15px;
  background: color-mix(in srgb, var(--kv-reader-text) 4%, transparent);
}
@media (max-width: 960px) {
  .kv-container { padding-right: 24px; padding-left: 24px; }
  .kv-admin-side { padding: 18px 20px; }
  .kv-admin-main { padding: 26px 24px 48px; }
}
@media (max-width: 680px) {
  .kv-container { padding-right: 18px; padding-left: 18px; }
  .kv-header-inner { height: 66px; }
  .kv-mobile-menu { padding: 8px 0 16px; }
  .kv-mobile-menu .kv-nav-link { padding: 11px 13px; }
  .kv-hero { min-height: 0; padding: 25px; margin-top: 22px; border-radius: 20px; }
  .kv-hero-title { font-size: clamp(2.2rem, 10vw, 3.2rem); }
  .kv-section { margin-top: 44px; }
  .kv-grid { gap: 14px; }
  .kv-detail-grid { margin-top: 24px; }
  .kv-admin-side { padding: 14px 16px; }
  .kv-admin-main { padding: 22px 16px 42px; }
  .kv-stat-card { min-height: 120px; padding: 16px; }
  .kv-qa { min-height: 78px; }
}
@media (max-width: 420px) {
  .kv-container { padding-right: 14px; padding-left: 14px; }
  .kv-hero { padding: 21px; }
  .kv-toolbar { padding: 13px; }
  .kv-admin-main { padding-right: 12px; padding-left: 12px; }
  .kv-modal { padding: 14px; }
  .kv-modal-box { padding: 21px; }
}

/* Modern SaaS visual system */
html { scroll-behavior: smooth; }
body {
  min-height: 100vh;
  background:
    radial-gradient(ellipse at 50% -18%, rgba(101, 88, 245, 0.10), transparent 44%),
    var(--kv-bg);
  letter-spacing: -0.01em;
}
.kv-container { max-width: 1240px; padding-right: 28px; padding-left: 28px; }
.kv-header {
  background: color-mix(in srgb, var(--kv-bg) 82%, transparent);
  border-bottom-color: color-mix(in srgb, var(--kv-border) 78%, transparent);
  box-shadow: 0 8px 28px -24px rgba(0, 0, 0, 0.55);
}
.kv-header-inner { height: 72px; gap: 28px; }
.kv-header-inner { position: relative; }
.kv-brand {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 1.3rem;
  letter-spacing: -0.055em;
  background: linear-gradient(110deg, var(--kv-text) 20%, var(--kv-accent) 72%, var(--kv-neon));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.kv-brand-mark {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 34px;
  border: 1px solid color-mix(in srgb, var(--kv-accent) 42%, var(--kv-border));
  border-radius: 11px;
  background: linear-gradient(145deg, var(--kv-accent), var(--kv-neon));
  box-shadow: 0 6px 16px -10px var(--kv-accent);
  color: #FFFFFF;
  font-size: 1rem;
  font-weight: 850;
  -webkit-text-fill-color: #FFFFFF;
}
.kv-nav { gap: 5px; }
.kv-nav-link {
  padding: 8px 12px;
  border: 0;
  border-radius: 9px;
  font-size: 0.8125rem;
  transition: color 0.18s ease, background-color 0.18s ease;
}
.kv-nav-link:hover, .kv-nav-link.active {
  color: var(--kv-text);
  background: var(--kv-surface-2);
}
.kv-header-actions { display: flex; align-items: center; gap: 10px; }
.kv-theme-toggle {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  padding: 0;
  border-radius: 14px;
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
  border-color: color-mix(in srgb, var(--kv-accent) 24%, var(--kv-border));
}
.kv-theme-toggle:hover {
  color: var(--kv-accent-hover);
  background: color-mix(in srgb, var(--kv-accent) 15%, var(--kv-surface));
  border-color: color-mix(in srgb, var(--kv-accent) 48%, var(--kv-border));
}
.kv-theme-toggle svg { width: 24px; height: 24px; }
.kv-nav-login {
  margin-left: 6px;
  padding: 8px 16px;
  color: #FFFFFF !important;
  background: linear-gradient(120deg, var(--kv-accent), #7669F7 65%, var(--kv-neon));
  box-shadow: 0 6px 18px -10px var(--kv-accent);
  font-weight: 700;
}
.kv-nav-login:hover, .kv-nav-login.active {
  color: #FFFFFF;
  background: linear-gradient(120deg, var(--kv-accent-hover), #8175FF 65%, var(--kv-neon));
}
.kv-mobile-btn { display: none; }
.kv-mobile-menu {
  display: none;
  padding: 0 0 16px;
}
.kv-mobile-menu .kv-nav-link { display: block; padding: 11px 12px; }
.kv-btn {
  min-height: 40px;
  padding: 9px 16px;
  border-radius: 10px;
  font-weight: 650;
  transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}
.kv-btn-primary {
  background: linear-gradient(120deg, var(--kv-accent), #7669F7 60%, var(--kv-neon));
  box-shadow: 0 6px 18px -10px var(--kv-accent);
}
.kv-btn-primary:hover {
  background: linear-gradient(120deg, var(--kv-accent-hover), #8175FF 60%, var(--kv-neon));
  box-shadow: 0 10px 24px -12px var(--kv-accent);
  transform: translateY(-1px);
}
.kv-btn-ghost {
  background: color-mix(in srgb, var(--kv-surface) 86%, transparent);
  border-color: var(--kv-border);
}
.kv-btn-ghost:hover { background: var(--kv-surface-2); border-color: color-mix(in srgb, var(--kv-accent) 55%, var(--kv-border)); }
.kv-hero {
  min-height: 380px;
  gap: clamp(24px, 5vw, 68px);
  padding: clamp(28px, 5vw, 56px);
  margin-top: 32px;
  border-radius: 24px;
  border-color: color-mix(in srgb, var(--kv-accent) 20%, var(--kv-border));
  background:
    radial-gradient(ellipse at 82% 18%, rgba(138, 124, 255, 0.13), transparent 36%),
    linear-gradient(135deg, var(--kv-surface), color-mix(in srgb, var(--kv-surface) 82%, var(--kv-surface-2)));
  box-shadow: 0 28px 80px -58px rgba(0, 0, 0, 0.72);
}
.kv-hero::before { opacity: 0.7; }
.kv-hero::after { opacity: 0.6; }
.kv-hero > * { position: relative; z-index: 1; }
.kv-hero-title {
  max-width: 14ch;
  font-size: clamp(2.15rem, 5vw, 3.65rem);
  letter-spacing: -0.065em;
  line-height: 1.04;
  margin: 18px 0;
}
.kv-hero .kv-meta-line { gap: 8px; }
.kv-hero .kv-cover-wrap {
  max-width: 300px !important;
  border-radius: 18px;
  box-shadow: 0 24px 60px -26px rgba(0, 0, 0, 0.65);
  transform: rotate(2deg);
  transition: transform 0.25s ease;
}
.kv-hero:hover .kv-cover-wrap { transform: rotate(0) translateY(-3px); }
.kv-kicker { letter-spacing: 0.14em; }
.kv-section { margin-top: 56px; }
.kv-section-head { margin-bottom: 20px; }
.kv-section-title { letter-spacing: -0.04em; font-size: 1.4rem; }
.kv-grid { gap: 20px; }
.kv-card {
  border-radius: 16px;
  border-color: color-mix(in srgb, var(--kv-border) 86%, transparent);
  box-shadow: 0 8px 28px -25px rgba(0, 0, 0, 0.72);
}
.kv-card:hover {
  transform: translateY(-5px);
  border-color: color-mix(in srgb, var(--kv-accent) 65%, var(--kv-border));
  box-shadow: 0 20px 44px -24px rgba(101, 88, 245, 0.42);
}
.kv-card .kv-cover-wrap { aspect-ratio: 3 / 4; background: var(--kv-surface-2); }
.kv-card-body { padding: 16px; gap: 9px; }
.kv-card-title { letter-spacing: -0.025em; }
.kv-chip {
  background: color-mix(in srgb, var(--kv-surface-2) 85%, transparent);
  border-color: var(--kv-border);
  padding: 4px 9px;
  font-size: 0.6875rem;
}
.kv-chip-accent { background: color-mix(in srgb, var(--kv-accent) 12%, var(--kv-surface)); }
.kv-toolbar {
  padding: 18px;
  gap: 12px;
  border-radius: 16px;
  box-shadow: 0 10px 30px -28px rgba(0, 0, 0, 0.7);
}
.kv-input, .kv-select, .kv-textarea {
  min-height: 42px;
  border-radius: 10px;
  background: var(--kv-bg);
}
.kv-detail-grid { gap: clamp(24px, 4vw, 48px); }
.kv-detail-grid > .kv-cover-wrap {
  max-width: 300px;
  border-radius: 18px;
  box-shadow: 0 22px 54px -28px rgba(0, 0, 0, 0.65);
}
.kv-table-wrap, .kv-stat-box, .kv-stat-card {
  border-radius: 16px;
  box-shadow: 0 10px 30px -28px rgba(0, 0, 0, 0.75);
}
.kv-chapter-row { border-radius: 12px; }
.kv-footer {
  margin-top: 80px;
  background: color-mix(in srgb, var(--kv-surface) 72%, transparent);
}
.kv-footer-inner { min-height: 56px; }
.kv-admin-side { background: color-mix(in srgb, var(--kv-surface) 92%, var(--kv-bg)); }
.kv-admin-nav-item { border-radius: 10px; }
.kv-admin-nav-item.active {
  background: color-mix(in srgb, var(--kv-accent) 12%, var(--kv-surface));
  box-shadow: inset 3px 0 0 var(--kv-accent);
}
.kv-stat-card, .kv-qa { border-radius: 16px; }
.kv-qa:hover { box-shadow: 0 16px 34px -24px rgba(101, 88, 245, 0.5); }
.kv-modal-box { border-radius: 18px; box-shadow: 0 28px 80px -28px rgba(0, 0, 0, 0.7); }
.kv-reader-app {
  --kv-reader-bg: #080A10;
  --kv-reader-text: #F1F3FA;
  --kv-reader-muted: #9AA4B9;
  min-height: 100vh;
  background: var(--kv-reader-bg);
  color: var(--kv-reader-text);
}
.kv-reader-app[data-theme="light"] {
  --kv-reader-bg: #F3F5FA;
  --kv-reader-text: #171B2C;
  --kv-reader-muted: #69738A;
}
.kv-reader-app[data-theme="sepia"] {
  --kv-reader-bg: #F1E8D5;
  --kv-reader-text: #3B2F2F;
  --kv-reader-muted: #76695B;
}
.kv-reader-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: color-mix(in srgb, var(--kv-reader-bg) 88%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--kv-reader-muted) 20%, transparent);
  backdrop-filter: blur(18px);
}
.kv-reader-top, .kv-reader-tools {
  width: min(1120px, 100%);
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}
.kv-reader-top { min-height: 76px; }
.kv-reader-heading { display: flex; align-items: center; gap: 14px; min-width: 0; }
.kv-reader-back {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--kv-reader-muted) 24%, transparent);
  border-radius: 12px;
  color: var(--kv-reader-text);
  font-size: 1.15rem;
  transition: background-color 0.16s ease, border-color 0.16s ease;
}
.kv-reader-back:hover, .kv-reader-chapter-link:hover {
  background: color-mix(in srgb, var(--kv-reader-text) 8%, transparent);
  border-color: color-mix(in srgb, var(--kv-accent) 60%, transparent);
}
.kv-reader-eyebrow {
  display: block;
  margin-bottom: 2px;
  color: var(--kv-reader-muted);
  font-size: 0.625rem;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.kv-reader-title {
  margin: 0;
  overflow: hidden;
  color: var(--kv-reader-text);
  font-size: 0.95rem;
  font-weight: 750;
  letter-spacing: -0.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kv-reader-subtitle { margin: 2px 0 0; color: var(--kv-reader-muted); font-size: 0.75rem; }
.kv-reader-chapter-nav { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
.kv-reader-chapter-link {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 7px 12px;
  border: 1px solid color-mix(in srgb, var(--kv-reader-muted) 24%, transparent);
  border-radius: 10px;
  color: var(--kv-reader-text);
  font-size: 0.75rem;
  font-weight: 650;
  transition: background-color 0.16s ease, border-color 0.16s ease;
}
.kv-reader-chapter-link.next {
  color: #FFFFFF;
  border-color: transparent;
  background: linear-gradient(120deg, var(--kv-accent), #7669F7 65%, var(--kv-neon));
}
.kv-reader-chapter-link.next:hover { filter: brightness(1.08); }
.kv-reader-tools {
  justify-content: flex-start;
  flex-wrap: wrap;
  min-height: 58px;
  padding-top: 8px;
  padding-bottom: 12px;
  border-top: 1px solid color-mix(in srgb, var(--kv-reader-muted) 12%, transparent);
}
.kv-reader-tool-label {
  margin-right: auto;
  color: var(--kv-reader-muted);
  font-size: 0.75rem;
  font-weight: 600;
}
.kv-reader-tools .kv-btn, .kv-reader-tools .kv-select {
  min-height: 36px;
  padding-top: 6px;
  padding-bottom: 6px;
  border-radius: 9px;
  font-size: 0.75rem;
}
.kv-reader-tools .kv-btn-ghost, .kv-reader-tools .kv-select {
  color: var(--kv-reader-text);
  border-color: color-mix(in srgb, var(--kv-reader-muted) 24%, transparent);
  background-color: color-mix(in srgb, var(--kv-reader-text) 5%, transparent);
}
.kv-reader-tools .kv-select { min-width: 100px; }
.kv-reader-stage { min-height: calc(100vh - 134px); background: var(--kv-reader-bg); }
.kv-reader-canvas {
  width: 100%;
  padding: 24px 16px 56px;
  gap: 0;
}
.kv-reader-canvas img {
  border-radius: 0;
  box-shadow: 0 12px 35px -22px rgba(0, 0, 0, 0.8);
}
.kv-reader-placeholder {
  width: 100%;
  aspect-ratio: 3 / 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  border: 1px solid color-mix(in srgb, var(--kv-reader-muted) 24%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--kv-reader-text) 4%, transparent);
  color: var(--kv-reader-muted);
  text-align: center;
}
.kv-reader-placeholder-title { margin-bottom: 6px; color: var(--kv-reader-text); font-weight: 700; }
.kv-reader-page-controls {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 18px 0 28px;
  color: var(--kv-reader-muted);
}
.kv-reader-page-count {
  min-width: 68px;
  text-align: center;
  color: var(--kv-reader-text);
  font-size: 0.8125rem;
}
.kv-reader-page-controls .kv-btn-ghost {
  color: var(--kv-reader-text);
  border-color: color-mix(in srgb, var(--kv-reader-muted) 24%, transparent);
  background: color-mix(in srgb, var(--kv-reader-text) 5%, transparent);
}
.kv-reader-end-nav {
  width: min(760px, 100%);
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin: 28px auto 0;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--kv-reader-muted) 20%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--kv-reader-text) 4%, transparent);
}
.kv-reader-end-nav .kv-reader-chapter-link { min-height: 44px; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Responsive */
.kv-mobile-btn { display: none; }
@media (max-width: 960px) {
  .kv-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .kv-admin-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .kv-hero { grid-template-columns: minmax(0, 1.15fr) minmax(220px, 0.85fr); }
  .kv-detail-grid { grid-template-columns: 240px minmax(0, 1fr); }
  .kv-hero .kv-cover-wrap { max-width: 260px !important; }
  .kv-admin-shell { flex-direction: column; }
  .kv-admin-side {
    position: static; width: 100%; height: auto; flex-direction: column;
    padding: 14px 16px; border-right: none; border-bottom: 1px solid var(--kv-border);
  }
  .kv-admin-nav { flex-direction: row; flex-wrap: wrap; }
  .kv-admin-nav-item { width: auto; }
  .kv-admin-side-foot { margin-top: 6px; padding-top: 10px; flex-direction: row; align-items: center; flex-wrap: wrap; }
  .kv-admin-main { max-width: none; padding: 20px 16px 40px; }
  .kv-qa-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 680px) {
  .kv-nav { display: none; }
  .kv-mobile-btn { display: inline-flex; }
  .kv-container { padding-right: 18px; padding-left: 18px; }
  .kv-header-inner { gap: 10px; }
  .kv-header-actions { gap: 7px; }
  .kv-mobile-menu { display: flex; flex-direction: column; gap: 4px; }
  .kv-mobile-menu .kv-nav-link { border-radius: 10px; }
  .kv-mobile-menu .kv-nav-link.active { color: var(--kv-accent); }
  .kv-mobile-menu .kv-nav-login { margin: 6px 0 0; color: #FFFFFF !important; }
  .kv-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
  .kv-admin-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .kv-hero { grid-template-columns: 1fr; gap: 22px; padding: 24px; margin-top: 20px; border-radius: 18px; }
  .kv-hero-title { font-size: clamp(2rem, 9vw, 3rem); }
  .kv-hero .kv-cover-wrap { max-width: 220px !important; justify-self: start !important; }
  .kv-detail-grid { grid-template-columns: minmax(0, 1fr); }
  .kv-detail-grid > .kv-cover-wrap { width: min(62%, 250px); }
  .kv-section { margin-top: 42px; }
  .kv-card-body { padding: 12px; gap: 7px; }
  .kv-card .kv-chip { padding: 3px 7px; font-size: 0.625rem; }
  .kv-card-title { font-size: 0.9rem; }
  .kv-form-grid { grid-template-columns: 1fr; }
  .kv-toasts { left: 20px; right: 20px; max-width: none; }
  .kv-qa-grid { grid-template-columns: 1fr; }
  .kv-admin-main { padding: 16px 14px 40px; }
  .kv-admin-title { font-size: 1.25rem; }
  .kv-reader-top, .kv-reader-tools { padding-right: 14px; padding-left: 14px; }
  .kv-reader-top { min-height: 66px; gap: 8px; }
  .kv-reader-heading { gap: 9px; }
  .kv-reader-title { max-width: 36vw; font-size: 0.84rem; }
  .kv-reader-subtitle { font-size: 0.6875rem; }
  .kv-reader-chapter-link { min-height: 36px; padding: 6px 9px; }
  .kv-reader-chapter-link .kv-reader-link-label { display: none; }
  .kv-reader-tools { gap: 7px; }
  .kv-reader-tool-label { width: 100%; margin: 0 0 2px; }
  .kv-reader-tools .kv-select { min-width: 0; max-width: 31%; flex: 1; }
  .kv-reader-canvas { padding: 12px 0 36px; }
  .kv-reader-page-controls { padding: 0 12px; }
  .kv-reader-end-nav { border-radius: 0; border-right: 0; border-left: 0; padding: 14px; }
}
@media (max-width: 420px) {
  .kv-container { padding-right: 14px; padding-left: 14px; }
  .kv-header-inner { height: 64px; }
  .kv-theme-toggle { width: 44px; height: 44px; flex-basis: 44px; }
  .kv-theme-toggle svg { width: 23px; height: 23px; }
  .kv-grid { grid-template-columns: minmax(0, 1fr); }
  .kv-card { display: grid; grid-template-columns: 88px minmax(0, 1fr); align-items: stretch; }
  .kv-card .kv-cover-wrap { height: 118px; min-height: 100%; aspect-ratio: auto; }
  .kv-card-body { justify-content: center; }
  .kv-hero { padding: 20px; }
  .kv-hero .kv-cover-wrap { max-width: 180px !important; }
  .kv-admin-grid { grid-template-columns: minmax(0, 1fr); }
  .kv-reader-back { width: 36px; height: 36px; flex-basis: 36px; }
  .kv-reader-title { max-width: 32vw; font-size: 0.78rem; }
  .kv-reader-eyebrow { font-size: 0.55rem; }
  .kv-reader-chapter-nav { gap: 5px; }
  .kv-reader-chapter-link { padding: 6px 8px; font-size: 0.7rem; }
  .kv-reader-tools .kv-btn, .kv-reader-tools .kv-select { font-size: 0.6875rem; }
}

/* Keep the refreshed visual system after legacy theme rules. */
body {
  background:
    radial-gradient(ellipse at 50% -18%, color-mix(in srgb, var(--kv-accent) 7%, transparent), transparent 46%),
    var(--kv-bg);
  letter-spacing: -0.012em;
}
.kv-container { max-width: 1280px; }
.kv-header {
  background: color-mix(in srgb, var(--kv-bg) 88%, transparent);
  border-bottom-color: color-mix(in srgb, var(--kv-border) 84%, transparent);
  box-shadow: 0 8px 26px -24px rgba(30, 35, 60, 0.42);
}
.kv-brand-mark {
  border: 0;
  border-radius: 12px;
  background: linear-gradient(145deg, var(--kv-accent), var(--kv-neon));
  box-shadow: 0 7px 16px -10px var(--kv-accent);
}
.kv-nav-link:hover, .kv-nav-link.active {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-nav-login, .kv-nav-login:hover, .kv-nav-login.active {
  color: #FFFFFF !important;
  background: var(--kv-accent);
  box-shadow: 0 7px 18px -12px var(--kv-accent);
}
.kv-nav-login:hover { background: var(--kv-accent-hover); }
.kv-theme-toggle {
  width: 42px;
  height: 42px;
  flex-basis: 42px;
  border-radius: 12px;
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 8%, var(--kv-surface));
  border-color: color-mix(in srgb, var(--kv-accent) 22%, var(--kv-border));
}
.kv-btn-primary, .kv-reader-chapter-link.next {
  color: #FFFFFF;
  background: var(--kv-accent);
  box-shadow: 0 7px 18px -12px var(--kv-accent);
}
.kv-btn-primary:hover, .kv-reader-chapter-link.next:hover {
  background: var(--kv-accent-hover);
  box-shadow: 0 10px 24px -14px var(--kv-accent);
  filter: none;
}
.kv-btn-ghost { background: var(--kv-surface); }
.kv-hero {
  border-color: color-mix(in srgb, var(--kv-accent) 16%, var(--kv-border));
  background:
    radial-gradient(ellipse at 87% 14%, color-mix(in srgb, var(--kv-accent) 12%, transparent), transparent 38%),
    linear-gradient(135deg, var(--kv-surface) 0%, color-mix(in srgb, var(--kv-neon) 6%, var(--kv-surface)) 100%);
  box-shadow: 0 24px 70px -58px rgba(40, 45, 80, 0.42);
}
.kv-hero::before, .kv-hero::after { opacity: 0.26; }
.kv-hero-title { font-weight: 800; letter-spacing: -0.075em; }
.kv-card {
  border-color: color-mix(in srgb, var(--kv-border) 88%, transparent);
  box-shadow: 0 8px 25px -24px rgba(30, 35, 60, 0.62);
}
.kv-card:hover {
  border-color: color-mix(in srgb, var(--kv-accent) 46%, var(--kv-border));
  box-shadow: 0 18px 38px -28px color-mix(in srgb, var(--kv-accent) 42%, transparent);
}
.kv-card .kv-cover-wrap { aspect-ratio: 3 / 4; background: var(--kv-surface-2); }
.kv-chip-accent {
  color: var(--kv-accent);
  border-color: color-mix(in srgb, var(--kv-accent) 25%, var(--kv-border));
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-toolbar, .kv-stat-card, .kv-table-wrap, .kv-stat-box, .kv-qa, .kv-modal-box {
  border-color: var(--kv-border);
  box-shadow: 0 10px 30px -27px rgba(30, 35, 60, 0.52);
}
.kv-input, .kv-select, .kv-textarea { background: var(--kv-surface); }
.kv-input:focus, .kv-select:focus, .kv-textarea:focus {
  border-color: var(--kv-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--kv-accent) 15%, transparent);
}
.kv-chapter-row {
  border-color: var(--kv-border);
  background: var(--kv-surface);
}
.kv-chapter-row:hover {
  border-color: color-mix(in srgb, var(--kv-accent) 42%, var(--kv-border));
  background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface));
}
table.kv-table th { color: var(--kv-text-muted); background: var(--kv-surface-2); }
.kv-footer {
  background: color-mix(in srgb, var(--kv-surface) 80%, transparent);
  border-top-color: var(--kv-border);
}
.kv-admin-side { background: var(--kv-surface); }
.kv-admin-nav-item.active {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-stat-ico, .kv-qa-ico {
  color: var(--kv-accent);
  background: color-mix(in srgb, var(--kv-accent) 9%, var(--kv-surface));
}
.kv-qa:hover {
  border-color: color-mix(in srgb, var(--kv-accent) 36%, var(--kv-border));
  box-shadow: 0 14px 28px -24px color-mix(in srgb, var(--kv-accent) 40%, transparent);
}
.kv-reader-app { --kv-reader-bg: #171923; }
.kv-reader-app[data-theme="light"] { --kv-reader-bg: #F4F5F9; }
.kv-reader-app[data-theme="sepia"] { --kv-reader-bg: #F2EBDD; }
.kv-reader-end-nav { border-radius: 15px; }
@media (max-width: 680px) {
  .kv-container { padding-right: 18px; padding-left: 18px; }
  .kv-hero { padding: 25px; margin-top: 22px; border-radius: 20px; }
  .kv-grid { gap: 14px; }
  .kv-detail-grid { margin-top: 24px; }
 }
 @media (max-width: 420px) {
   .kv-container { padding-right: 14px; padding-left: 14px; }
   .kv-hero { padding: 21px; }
   .kv-toolbar { padding: 13px; }
 }
 /* ===== Admin redesign: analytics dashboard ===== */
 .kv-admin-shell { background: radial-gradient(1200px 600px at 80% -10%, color-mix(in srgb, var(--kv-accent) 12%, transparent), transparent), var(--kv-bg); }
 .kv-admin-side { backdrop-filter: blur(12px); }
 .kv-kpi-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin: 18px 0 24px; }
 .kv-kpi { position: relative; overflow: hidden; padding: 18px 20px; border-radius: 16px; background: var(--kv-surface); border: 1px solid var(--kv-border); transition: transform .18s ease, box-shadow .18s ease; }
 .kv-kpi:hover { transform: translateY(-2px); box-shadow: 0 12px 30px color-mix(in srgb, var(--kv-accent) 14%, transparent); }
 .kv-kpi .ico { width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; background: color-mix(in srgb, var(--kv-accent) 14%, var(--kv-surface-2)); color: var(--kv-accent); margin-bottom: 12px; }
 .kv-kpi .lbl { font-size: .78rem; color: var(--kv-text-muted); text-transform: uppercase; letter-spacing: .06em; font-weight: 600; }
 .kv-kpi .val { font-size: 1.85rem; font-weight: 800; letter-spacing: -.03em; margin-top: 4px; font-family: var(--kv-font-mono, monospace); }
 .kv-kpi .delta { font-size: .75rem; color: var(--kv-text-muted); margin-top: 6px; }
 .kv-chart-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 16px; padding: 20px; }
 .kv-chart-title { font-size: .95rem; font-weight: 700; margin: 0 0 4px; }
 .kv-chart-sub { font-size: .78rem; color: var(--kv-text-muted); margin: 0 0 14px; }
 .kv-bar-chart { display: flex; align-items: flex-end; gap: 10px; height: 180px; padding: 8px 4px 0; border-bottom: 1px solid var(--kv-border); }
 .kv-bar-col { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 6px; min-width: 0; }
 .kv-bar { width: 100%; border-radius: 8px 8px 0 0; background: linear-gradient(180deg, var(--kv-accent), color-mix(in srgb, var(--kv-accent) 40%, transparent)); min-height: 4px; transition: height .3s ease; position: relative; }
 .kv-bar:hover { filter: brightness(1.15); }
 .kv-bar-label { font-size: .7rem; color: var(--kv-text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; text-align: center; }
 .kv-bar-val { font-size: .7rem; font-weight: 600; color: var(--kv-text); }
 .kv-two-col { display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; margin: 16px 0; }
 .kv-card { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 16px; padding: 20px; }
 .kv-card h3 { margin: 0 0 12px; font-size: 1rem; font-weight: 700; }
 .kv-user-table img { width: 32px; height: 32px; border-radius: 50%; object-fit: cover; vertical-align: middle; margin-right: 8px; }
 .kv-role-badge { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; }
 .kv-role-badge.admin { background: color-mix(in srgb, var(--kv-accent) 18%, transparent); color: var(--kv-accent); }
 .kv-role-badge.member { background: var(--kv-surface-2); color: var(--kv-text-muted); }
 .kv-dropzone { border: 2px dashed var(--kv-border); border-radius: 14px; padding: 28px; text-align: center; color: var(--kv-text-muted); background: var(--kv-surface-2); cursor: pointer; transition: border-color .15s, background .15s; }
 .kv-dropzone.drag { border-color: var(--kv-accent); background: color-mix(in srgb, var(--kv-accent) 8%, var(--kv-surface-2)); color: var(--kv-text); }
 .kv-dropzone .ico { font-size: 2rem; margin-bottom: 8px; }
 .kv-toolbar-wysi { display: flex; flex-wrap: wrap; gap: 6px; padding: 8px; border: 1px solid var(--kv-border); border-bottom: none; border-radius: 10px 10px 0 0; background: var(--kv-surface-2); }
 .kv-toolbar-wysi button { padding: 4px 10px; border-radius: 6px; border: 1px solid var(--kv-border); background: var(--kv-surface); color: var(--kv-text); font-size: .8rem; font-weight: 600; cursor: pointer; }
 .kv-toolbar-wysi button:hover { background: var(--kv-accent); color: #fff; border-color: var(--kv-accent); }
 .kv-wysi-textarea { border-radius: 0 0 10px 10px !important; }
 @media (max-width: 900px) { .kv-kpi-grid { grid-template-columns: repeat(2, 1fr); } .kv-two-col { grid-template-columns: 1fr; } }
  @media (max-width: 520px) { .kv-kpi-grid { grid-template-columns: 1fr; } }
  /* ===== Admin redesign: top navigation layout ===== */
  .kv-admin-shell.kv-admin-top { display: block; min-height: 100vh; background: radial-gradient(1200px 600px at 50% -20%, color-mix(in srgb, var(--kv-accent) 14%, transparent), transparent), var(--kv-bg); }
  .kv-admin-topbar-new { display: flex; align-items: center; gap: 16px; padding: 14px 28px; background: color-mix(in srgb, var(--kv-surface) 80%, transparent); backdrop-filter: blur(14px); border-bottom: 1px solid var(--kv-border); position: sticky; top: 0; z-index: 40; flex-wrap: wrap; }
  .kv-admin-topbar-new .kv-admin-logo { font-size: 1.1rem; font-weight: 800; color: var(--kv-text); text-decoration: none; }
  .kv-admin-nav-h { display: flex; gap: 4px; flex: 1; justify-content: center; flex-wrap: wrap; }
  .kv-admin-nav-h .kv-admin-nav-item { padding: 8px 14px; border-radius: 10px; background: transparent; color: var(--kv-text-muted); font-weight: 600; font-size: .85rem; border: none; cursor: pointer; }
  .kv-admin-nav-h .kv-admin-nav-item:hover { background: var(--kv-surface-2); color: var(--kv-text); }
  .kv-admin-nav-h .kv-admin-nav-item.active { background: color-mix(in srgb, var(--kv-accent) 18%, transparent); color: var(--kv-accent); }
  .kv-admin-quickbar { padding: 12px 28px; border-bottom: 1px solid var(--kv-border); background: var(--kv-surface); display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
  .kv-admin-quicklink { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 8px; font-size: .8rem; color: var(--kv-text-muted); text-decoration: none; border: 1px solid var(--kv-border); background: var(--kv-surface-2); transition: border-color .12s, color .12s; }
  .kv-admin-quicklink:hover { border-color: var(--kv-accent); color: var(--kv-accent); }
  .kv-admin-main-full { max-width: 1400px; margin: 0 auto; padding: 28px 32px 48px; }
  .kv-admin-pagehead { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin-bottom: 24px; padding-bottom: 16px; border-bottom: 1px solid var(--kv-border); }
  /* ===== Admin redesign: full shell restyle ===== */
  .kv-admin-shell { font-family: var(--kv-font-body, inherit); }
  .kv-admin-shell .kv-stat-box { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 16px; padding: 24px; box-shadow: 0 4px 20px color-mix(in srgb, #000 6%, transparent); }
  .kv-admin-shell .kv-section-title { letter-spacing: -0.02em; }
  .kv-admin-shell .kv-input, .kv-admin-shell .kv-select, .kv-admin-shell .kv-textarea {
    background: var(--kv-surface-2); border: 1px solid var(--kv-border); border-radius: 10px;
    padding: 10px 12px; font-size: .9rem; transition: border-color .15s, box-shadow .15s;
  }
  .kv-admin-shell .kv-input:focus, .kv-admin-shell .kv-select:focus, .kv-admin-shell .kv-textarea:focus {
    outline: none; border-color: var(--kv-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--kv-accent) 18%, transparent);
  }
  .kv-admin-shell .kv-table { border-radius: 12px; overflow: hidden; border: 1px solid var(--kv-border); }
  .kv-admin-shell .kv-table th { background: var(--kv-surface-2); font-weight: 700; text-transform: uppercase; font-size: .72rem; letter-spacing: .06em; color: var(--kv-text-muted); padding: 12px 14px; }
  .kv-admin-shell .kv-table td { padding: 12px 14px; border-top: 1px solid var(--kv-border); vertical-align: middle; }
  .kv-admin-shell .kv-table tbody tr:hover { background: color-mix(in srgb, var(--kv-accent) 4%, var(--kv-surface)); }
  .kv-admin-shell .kv-table-wrap { border-radius: 12px; overflow: auto; }
  .kv-admin-shell .kv-btn-primary { background: linear-gradient(135deg, var(--kv-accent), color-mix(in srgb, var(--kv-accent) 70%, #6366f1)); border: none; box-shadow: 0 6px 16px color-mix(in srgb, var(--kv-accent) 30%, transparent); }
  .kv-admin-shell .kv-btn-primary:hover { filter: brightness(1.08); transform: translateY(-1px); }
  .kv-admin-shell .kv-btn-ghost { border: 1px solid var(--kv-border); background: var(--kv-surface); }
  .kv-admin-shell .kv-btn-ghost:hover { background: var(--kv-surface-2); border-color: var(--kv-accent); color: var(--kv-accent); }
  .kv-admin-shell .kv-btn-danger-ghost { border: 1px solid color-mix(in srgb, #ef4444 40%, var(--kv-border)); color: #ef4444; background: var(--kv-surface); }
  .kv-admin-shell .kv-btn-danger-ghost:hover { background: color-mix(in srgb, #ef4444 10%, var(--kv-surface)); }
  .kv-admin-shell .kv-toolbar { background: var(--kv-surface); border: 1px solid var(--kv-border); border-radius: 14px; padding: 14px; display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
  .kv-admin-shell .kv-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
  .kv-admin-shell .kv-form-grid > label { display: flex; flex-direction: column; gap: 6px; font-size: .85rem; font-weight: 600; color: var(--kv-text-muted); }
  .kv-admin-shell .kv-form-grid > label input, .kv-admin-shell .kv-form-grid > label select, .kv-admin-shell .kv-form-grid > label textarea { margin-top: 0; }
  .kv-admin-shell .kv-qa-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
  .kv-admin-shell .kv-qa { display: flex; gap: 12px; align-items: center; padding: 14px; border-radius: 12px; border: 1px solid var(--kv-border); background: var(--kv-surface); cursor: pointer; transition: border-color .15s, transform .15s; }
  .kv-admin-shell .kv-qa:hover { border-color: var(--kv-accent); transform: translateY(-2px); }
  .kv-admin-shell .kv-qa-ico { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: color-mix(in srgb, var(--kv-accent) 14%, var(--kv-surface-2)); color: var(--kv-accent); }
  .kv-admin-shell .kv-admin-side { background: color-mix(in srgb, var(--kv-surface) 85%, transparent); border-right: 1px solid var(--kv-border); }
  .kv-admin-shell .kv-admin-nav-item { border-radius: 10px; transition: background .12s, color .12s; }
  .kv-admin-shell .kv-admin-nav-item.active { background: color-mix(in srgb, var(--kv-accent) 16%, transparent); color: var(--kv-accent); font-weight: 700; }
  .kv-admin-shell .kv-admin-logo { font-weight: 800; letter-spacing: -0.02em; }
  .kv-admin-shell .kv-admin-logo span { color: var(--kv-accent); }
  .kv-admin-shell .kv-admin-chip { background: var(--kv-surface-2); border: 1px solid var(--kv-border); border-radius: 999px; padding: 6px 12px; font-size: .75rem; }
  .kv-admin-shell .kv-admin-topbar { margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--kv-border); }
  .kv-admin-shell .kv-admin-title { font-size: 1.6rem; font-weight: 800; letter-spacing: -0.03em; }
  .kv-admin-shell .kv-admin-sub { color: var(--kv-text-muted); font-size: .875rem; margin-top: 4px; }
  .kv-admin-shell .kv-page-thumb { border-radius: 8px; border: 1px solid var(--kv-border); }
  @media (max-width: 900px) { .kv-admin-shell .kv-form-grid { grid-template-columns: 1fr; } .kv-admin-shell .kv-qa-grid { grid-template-columns: 1fr; } }

body.script:
//
(function () {
  'use strict';

  /* =========================================================================
     UBAH KONFIGURASI DI SINI SEBELUM MEMASANG DI BLOGGER
     CATATAN KEAMANAN: Jangan pernah menaruh secret OAuth atau token bot
     Telegram di dalam file XML ini. Gunakan environment Vercel.
     ========================================================================= */
  /* =========================================================================
     ARSITEKTUR & INTEGRASI (DOKUMENTASI - BACA SEBELUM DEPLOY)
     =========================================================================
     KOMPONEN:
     1. BLOGGER (frontend): file XML ini. Menayangkan SPA pembaca. Blogger TIDAK
        bisa menjalankan kode server - semua rahasia HARUS di environment Vercel.
     2. VERCEL FUNCTIONS (folder proyek: api/) menyimpan secrets:
        TELEGRAM_BOT_TOKEN, TELEGRAM_STORAGE_CHAT_ID, TOKEN_SECRET,
        PUBLIC_API_URL, ALLOWED_ORIGINS, dan credential OAuth Google/Discord.
        Backend ini tidak memakai database selain Telegram.
        Pemetaan ke tema Blogger:
        - CONFIG.API_BASE_URL  = PUBLIC_API_URL  (origin Vercel yang sama)
        - return_to OAuth      = origin blog      (harus terdaftar di ALLOWED_ORIGINS)
        Endpoint minimum yang dipanggil frontend:
        - GET  /api/auth/{google|discord}/start dan /callback -> login OAuth
        - GET  /api/auth/me                -> profil dan role sesi aktif
        - GET  /api/catalog               -> { manga, chapters, comments }
        - POST /api/admin/upload-dual     -> simpan ke Telegram dan kembalikan
                                             URL proxy /api/media/{file_id}
        - POST /api/admin/save-manga      -> simpan/ubah data manga
        - POST /api/admin/save-chapter    -> simpan/ubah data chapter
        - POST /api/admin/delete-manga    -> { id }
        - POST /api/admin/delete-chapter  -> { id }
        - POST /api/admin/delete-comment  -> { id }
        - POST /api/admin/comment-status  -> { id, status }
        Semua endpoint admin memverifikasi header: Authorization: Bearer <token>.
     3. TELEGRAM menjadi penyimpanan tunggal: katalog, chapter, dan komentar
        tersimpan sebagai dokumen JSON yang dipin; gambar tersimpan sebagai
        dokumen di chat Telegram yang sama. Backend membaca pointer melalui
        pesan yang dipin dan mem-proxy
        gambar lewat /api/media/{file_id}. Bot token tidak dikirim ke browser.
     BATASAN:
     - Snapshot disimpan sebagai dokumen JSON Telegram (maks. 18 MiB),
        dan diperbarui pada pesan dokumen yang sama.
     - Dokumen snapshot katalog harus menjadi pesan yang dipin di chat Telegram.
     - Gunakan satu sesi admin untuk mencegah perubahan serentak saling menimpa.
     - Upload JPEG/PNG/WebP maksimal 3 MiB per berkas (batas request Vercel).
     CATATAN JUJUR:
      - Tanpa API_BASE_URL (diisi = PUBLIC_API_URL), situs jalan mode lokal (localStorage).
     - Panduan deploy Vercel ada di README.md.
     - Notifikasi chapter baru butuh backend (mis. polling feed / bot
        broadcast ke channel) - tidak mungkin dari Blogger saja.
     - Akun lintas perangkat butuh backend; mode lokal menyimpan di browser.
     - Jangan unggah manga berhak cipta tanpa izin pemilik.
     ========================================================================= */
   var CONFIG = {
    SITE_NAME: 'NexaManga',                 /* UBAH: nama website Anda */
    SITE_TAGLINE: 'Platform baca manga berbahasa Indonesia cepat & nyaman.',
    /* Harus identik dengan PUBLIC_API_URL di .env / Vercel Environment Variables.
       Contoh: 'https://nexamanga-nexamanga.vercel.app' (tanpa slash di akhir).
       Kosongkan hanya jika ingin mode lokal tanpa backend. */
    API_BASE_URL: 'https://nexamanga-nexamanga.vercel.app',
    DEFAULT_THEME: 'light', /* 'dark' atau 'light' */
    ITEMS_PER_PAGE: 8,
    CONTACT_EMAIL: 'redaksi@nexamanga.example' /* UBAH: email redaksi */
  };

  /* =========================================================================
     DATA CONTOH LEGAL (FALLBACK JIKA API_BASE_URL BELUM DIHUBUNGKAN)
     ========================================================================= */
  var SAMPLE_DATA = {
    manga: [
      {
        id: 'mng-001',
        slug: 'kronik-astral-2099',
        title: 'Kronik Astral 2099',
        altTitle: 'Neo-Jakarta Courier Protocol',
        author: 'Raka Pratama',
        synopsis: 'Di tahun 2099, kurir data lapis baja Arga mengantar paket terenkripsi melintasi distrik atas Neo-Jakarta hingga menemukan cetak biru memori kota.',
        coverBloggerUrl: 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiSamplePlaceholder01/s800/cover-placeholder.png',
        genres: ['Sci-Fi', 'Aksi', 'Cyberpunk'],
        type: 'Manga',
        status: 'Ongoing',
        rating: 4.9,
        views: 128450,
        featured: true,
        recommended: true,
        updatedAt: '2026-11-13'
      },
      {
        id: 'mng-002',
        slug: 'pedang-gerhana',
        title: 'Pedang Gerhana',
        altTitle: 'Kurogane no Nisshoku',
        author: 'Dian Kusuma',
        synopsis: 'Setiap seratus tahun, gerhana matahari membangunkan bayangan kuno dari lembah abu. Pengembara tanpa nama membawa bilah obsidian.',
        coverBloggerUrl: 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiSamplePlaceholder02/s800/cover-placeholder.png',
        genres: ['Fantasi', 'Aksi', 'Petualangan'],
        type: 'Manga',
        status: 'Ongoing',
        rating: 4.8,
        views: 96320,
        featured: true,
        recommended: true,
        updatedAt: '2026-11-12'
      },
      {
        id: 'mng-003',
        slug: 'taman-lentera',
        title: 'Taman Lentera',
        altTitle: 'Konservatori Senja',
        author: 'Nadia Larasati',
        synopsis: 'Rumah kaca yang hanya buka selepas matahari terbenam tempat ingatan pengunjung dititipkan pada tanaman bioluminesensi.',
        coverBloggerUrl: 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiSamplePlaceholder03/s800/cover-placeholder.png',
        genres: ['Misteri', 'Drama', 'Slice of Life'],
        type: 'Manhwa',
        status: 'Ongoing',
        rating: 4.7,
        views: 64110,
        featured: false,
        recommended: true,
        updatedAt: '2026-11-10'
      }
    ],
    chapters: [
      {
        id: 'ch-001-1', mangaId: 'mng-001', number: 1, title: 'Protokol Pengiriman Hujan', publishedAt: '2026-11-01',
        pages: [
          { order: 1, bloggerUrl: '', telegramFileId: 'BQACAgUAAxkBAA_DEMO_01', fileName: '01.jpg' },
          { order: 2, bloggerUrl: '', telegramFileId: 'BQACAgUAAxkBAA_DEMO_02', fileName: '02.jpg' }
        ]
      },
      {
        id: 'ch-001-2', mangaId: 'mng-001', number: 2, title: 'Menara Relai Selatan', publishedAt: '2026-11-07',
        pages: [
          { order: 1, bloggerUrl: '', telegramFileId: 'BQACAgUAAxkBAA_DEMO_03', fileName: '01.jpg' }
        ]
      },
      {
        id: 'ch-002-1', mangaId: 'mng-002', number: 1, title: 'Langit di Atas Lembah Abu', publishedAt: '2026-11-03',
        pages: [
          { order: 1, bloggerUrl: '', telegramFileId: 'BQACAgUAAxkBAA_DEMO_04', fileName: '01.jpg' }
        ]
      }
    ],
    comments: [
      { id: 'c1', mangaId: 'mng-001', authorName: 'Fajar', content: 'Mode baca vertikalnya sangat ringan di ponsel.', createdAt: '2026-11-13', status: 'approved' }
    ]
  };

  /* =========================================================================
     STATE & PERSISTENSI LOKAL
     ========================================================================= */
  var state = {
    route: 'home',
    params: {},
    theme: localStorage.getItem('kv_theme') || CONFIG.DEFAULT_THEME,
    /* Data dimuat dari: backend API -> data lokal admin -> data contoh */
    data: JSON.parse(localStorage.getItem('kv_local_data') || 'null') || JSON.parse(JSON.stringify(SAMPLE_DATA)),
    loading: false,
    error: null,
    search: '',
    filterGenre: 'Semua',
    filterStatus: 'Semua',
    filterType: 'Semua',
    sortBy: 'terbaru',
    page: 1,
    chapterSortAsc: false,
    readerMode: 'vertical', // 'vertical' | 'paged'
    readerWidth: 760,
    readerTheme: 'dark',
    readerDir: 'ltr', // 'ltr' | 'rtl'
    currentPageIdx: 0,
    user: null,
    bookmarks: JSON.parse(localStorage.getItem('kv_bookmarks') || '[]'),
    history: JSON.parse(localStorage.getItem('kv_history') || '[]'),
    adminToken: sessionStorage.getItem('kv_session_token') || '',
    mobileMenuOpen: false,
    refocusSearch: false,
    /* --- State panel admin & moderasi --- */
    adminTab: 'dashboard',
    adminForm: null,            // form manga aktif (objek) atau null = daftar
    adminChapterForm: null,     // form chapter aktif (objek) atau null
    adminChapterMangaId: '',
    adminSearch: '',
    adminRefocusSearch: false,
    adminExpandedManga: null,
    commentFilter: 'Semua',
    commentNotice: '',
     pendingDelete: null,        // { type, id, label, confirmLabel }
     toasts: [],
     usersCache: undefined
   };

  /* Persistensi lokal: perubahan admin disimpan ke localStorage agar
     tidak hilang saat reload (mode demo tanpa backend). */
  function persistData() {
    try { localStorage.setItem('kv_local_data', JSON.stringify(state.data)); } catch (e) { /* kuota penuh */ }
  }

  function uid(prefix) {
    return prefix + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7);
  }

  function slugify(text) {
    return String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }

  function today() {
    return new Date().toISOString().slice(0, 10);
  }

  function mangaById(id) {
    return state.data.manga.filter(function (m) { return m.id === id; })[0] || null;
  }

  function chapterById(id) {
    return state.data.chapters.filter(function (c) { return c.id === id; })[0] || null;
  }

  /* Sinkronisasi ke Vercel (hanya jika API_BASE_URL aktif) */
  var apiSyncQueue = Promise.resolve();
  function apiSync(path, payload) {
    if (!CONFIG.API_BASE_URL) return;
    apiSyncQueue = apiSyncQueue.then(function () {
      return fetch(CONFIG.API_BASE_URL + path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
        body: JSON.stringify(payload)
      }).then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
      });
    }).catch(function (err) {
      toast('Tersimpan lokal, tetapi gagal sinkron ke server (' + path + '): ' + err.message, 'warn');
    });
  }

  /* Notifikasi toast (tidak ikut terhapus saat render ulang: diluar #kv-app) */
  function toast(msg, type) {
    var wrap = document.getElementById('kv-toasts');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.id = 'kv-toasts';
      wrap.className = 'kv-toasts';
      wrap.setAttribute('role', 'status');
      wrap.setAttribute('aria-live', 'polite');
      document.body.appendChild(wrap);
    }
    var t = document.createElement('div');
    t.className = 'kv-toast' + (type ? ' kv-toast-' + type : '');
    t.textContent = msg;
    wrap.appendChild(t);
    setTimeout(function () { if (t.parentNode) t.parentNode.removeChild(t); }, 4000);
  }

  function confirmDelete(type, id, label, confirmLabel) {
    state.pendingDelete = { type: type, id: id, label: label, confirmLabel: confirmLabel || 'Hapus' };
    render();
  }

  /* Ikon SVG inline (stroke currentColor) untuk menu & tombol console admin */
  function kvIcon(name) {
    var p = {
      grid: '<path d="M3 3h7v7H3z"/><path d="M14 3h7v7h-7z"/><path d="M3 14h7v7H3z"/><path d="M14 14h7v7h-7z"/>',
      book: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
      layers: '<path d="m12 2 10 6-10 6L2 8l10-6z"/><path d="m2 14 10 6 10-6"/>',
      chat: '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
      gear: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09a1.65 1.65 0 0 0-1-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09a1.65 1.65 0 0 0 1.51-1 1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33h.01a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51h.01a1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82v.01a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>',
      plus: '<path d="M12 5v14"/><path d="M5 12h14"/>',
      out: '<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/>',
      globe: '<circle cx="12" cy="12" r="10"/><path d="M2 12h20"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>',
      eye: '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>',
      users: '<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
      trend: '<path d="m23 6-9.5 9.5-5-5L1 18"/><path d="M17 6h6v6"/>',
      zap: '<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/>',
      chev: '<path d="m6 9 6 6 6-6"/>'
    };
    return '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (p[name] || '') + '</svg>';
  }

  /* Chip pill gaya SaaS untuk meta informasi */
  function kvChip(text, accent, mono) {
    return '<span class="kv-chip' + (accent ? ' kv-chip-accent' : '') + (mono ? ' kv-mono' : '') + '">' + escapeHtml(text) + '</span>';
  }

  function applyTheme() {
    if (state.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('kv_theme', state.theme);
    var metaTheme = document.querySelector('meta[name="theme-color"]');
    if (metaTheme) metaTheme.setAttribute('content', state.theme === 'dark' ? '#0B0E17' : '#F5F7FB');
  }

  function escapeHtml(str) {
    return String(str || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function svgFallbackCover(title) {
    var safe = escapeHtml(title || 'Manga');
    return '<div style="width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:16px;text-align:center;background:linear-gradient(145deg,#111827,#1e1b4b);color:#e2e8f0;">' +
      '<div style="font-size:0.75rem;opacity:0.7;margin-bottom:6px;">SAMPUL CONTOH</div>' +
      '<div style="font-weight:700;font-size:0.95rem;">' + safe + '</div>' +
    '</div>';
  }

  function renderCover(url, title) {
    if (!url || url.indexOf('SamplePlaceholder') !== -1) {
      return svgFallbackCover(title);
    }
    return '<img src="' + escapeHtml(url) + '" alt="Sampul ' + escapeHtml(title) + '" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';"/>' +
      '<div style="display:none;width:100%;height:100%;align-items:center;justify-content:center;padding:16px;text-align:center;background:#111827;color:#cbd5e1;">' + escapeHtml(title) + '</div>';
  }

  function parseRoute() {
    var legacyRoute = window.location.hash.indexOf('#/') === 0 ? window.location.hash.slice(1) : '';
    var routePath = legacyRoute || window.location.pathname;
    if (!routePath || routePath === '/') routePath = '/';
    if (routePath.charAt(0) !== '/') routePath = '/' + routePath;

    var query = window.location.search.replace(/^\?/, '').split('&').filter(function (part) {
      var pair = part.split('=');
      return part && !(pair[0] === 'm' && pair[1] === '1');
    }).join('&');
    var cleanUrl = legacyRoute
      ? window.location.pathname + (query ? '?' + query : '') + '#' + routePath
      : routePath + (query ? '?' + query : '');
    if (window.location.pathname + window.location.search + window.location.hash !== cleanUrl) {
      window.history.replaceState(null, '', cleanUrl);
    }

    var parts = routePath.split('/').filter(Boolean);
    if (parts.length === 0) { state.route = 'home'; state.params = {}; return; }
    if (parts[0] === 'katalog') { state.route = 'catalog'; state.params = {}; return; }
    if (parts[0] === 'manga' && parts[1]) { state.route = 'detail'; state.params = { slug: parts[1] }; return; }
    if (parts[0] === 'baca' && parts[1] && parts[2]) { state.route = 'reader'; state.params = { slug: parts[1], chapterId: parts[2] }; state.currentPageIdx = 0; return; }
    if (parts[0] === 'akun') { state.route = 'account'; state.params = {}; return; }
    if (parts[0] === 'admin') { state.route = 'admin'; state.params = {}; return; }
    if (['tentang', 'kontak', 'privasi', 'ketentuan'].indexOf(parts[0]) !== -1) {
      state.route = 'info'; state.params = { page: parts[0] }; return;
    }
    state.route = '404'; state.params = {};
  }

  function navigate(path) {
    var routePath = String(path || '/').replace(/^#/, '');
    if (routePath.charAt(0) !== '/') routePath = '/' + routePath;
    var routeHash = '#' + routePath;
    if (window.location.hash !== routeHash) {
      window.history.pushState(null, '', routeHash);
    }
    state.mobileMenuOpen = false;
    state.commentNotice = null;
    parseRoute();
    render();
    window.scrollTo(0, 0);
  }

  function syncFromApi() {
    if (!CONFIG.API_BASE_URL) return;
    state.loading = true;
    render();
    var headers = {};
    if (state.adminToken) headers.Authorization = 'Bearer ' + state.adminToken;
    fetch(CONFIG.API_BASE_URL + '/api/catalog', { headers: headers })
      .then(function (r) {
        if (r.status === 409) throw new Error('Database belum diinisialisasi. Login sebagai admin (Google/Discord) sekali untuk memulai.');
        if (!r.ok) throw new Error('Gagal memuat katalog dari server proxy (HTTP ' + r.status + ').');
        return r.json();
      })
      .then(function (json) {
        state.data = json;
        state.loading = false;
        state.error = null;
        render();
      })
      .catch(function (err) {
        state.loading = false;
        state.error = err.message;
        render();
      });
  }

  function initializeAuth() {
    sessionStorage.removeItem('kv_admin_token');
     var callbackToken = new URLSearchParams(window.location.search).get('auth_token');
     if (callbackToken) {
       state.adminToken = callbackToken;
       sessionStorage.setItem('kv_session_token', callbackToken);
       window.history.replaceState(null, '', window.location.pathname + window.location.hash);
     }
     if (!state.adminToken || !CONFIG.API_BASE_URL) {
       state.user = null;
       render();
       syncFromApi();
       return;
     }
     render();
     (function claimAdminIfNeeded() {
       return fetch(CONFIG.API_BASE_URL + '/api/auth/claim-admin', {
         method: 'POST',
         headers: { Authorization: 'Bearer ' + state.adminToken }
       }).then(function (response) {
         if (!response.ok) return null;
         return response.json();
       }).then(function (result) {
         if (result && result.token) {
           state.adminToken = result.token;
           sessionStorage.setItem('kv_session_token', result.token);
         }
       }).catch(function () {});
     })().then(function () {
       fetch(CONFIG.API_BASE_URL + '/api/auth/me', {
         headers: { Authorization: 'Bearer ' + state.adminToken }
       }).then(function (response) {
         if (!response.ok) throw new Error('Sesi tidak valid.');
         return response.json();
        }).then(function (result) {
          state.user = result.user || null;
          if (state.user && result.role) state.user.role = result.role;
        }).catch(function () {
         state.adminToken = '';
         state.user = null;
         sessionStorage.removeItem('kv_session_token');
       }).then(function () {
         render();
         syncFromApi();
       });
     });
  }

  function collectGenres() {
    var out = [];
    state.data.manga.forEach(function (m) { (m.genres || []).forEach(function (g) { if (out.indexOf(g) === -1) out.push(g); }); });
    return out;
  }

  function collectTypes() {
    var out = [];
    state.data.manga.forEach(function (m) { if (m.type && out.indexOf(m.type) === -1) out.push(m.type); });
    return out;
  }

  /* =========================================================================
     RENDER HEADER & FOOTER
     ========================================================================= */
  function renderHeader() {
    if (state.route === 'reader' || state.route === 'admin') return '';
    var navItems = [
      { path: '/', label: 'Beranda', key: 'home' },
      { path: '/katalog', label: 'Katalog', key: 'catalog' },
      { path: '/akun', label: state.user ? 'Akun Saya' : 'Masuk', key: 'account' },
      { path: '/tentang', label: 'Tentang', key: 'info' },
      { path: '/admin', label: 'Admin', key: 'admin' }
    ];
    var linksHtml = navItems.map(function (item) {
      var cls = 'kv-nav-link' + (item.key === 'account' ? ' kv-nav-login' : '') + (state.route === item.key ? ' active' : '');
      return '<a class="' + cls + '" href="' + item.path + '"' + (state.route === item.key ? ' aria-current="page"' : '') + '>' + item.label + '</a>';
    }).join('');
    var themeLabel = state.theme === 'dark' ? 'Aktifkan mode terang' : 'Aktifkan mode gelap';
    var themeIcon = state.theme === 'dark'
      ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>'
      : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13z"/></svg>';

    return '<header class="kv-header">' +
      '<div class="kv-container kv-header-inner">' +
        '<a class="kv-brand" href="#/" aria-label="' + escapeHtml(CONFIG.SITE_NAME) + ' - beranda">' +
          '<span class="kv-brand-mark" aria-hidden="true">N</span>' +
          '<span>' + escapeHtml(CONFIG.SITE_NAME) + '</span>' +
        '</a>' +
        '<nav class="kv-nav" aria-label="Navigasi Utama">' + linksHtml + '</nav>' +
        '<div class="kv-header-actions">' +
          '<button type="button" class="kv-btn kv-btn-ghost kv-theme-toggle" data-action="toggle-theme" aria-label="' + themeLabel + '" title="' + themeLabel + '">' + themeIcon + '</button>' +
          '<button type="button" class="kv-btn kv-btn-ghost kv-mobile-btn" data-action="toggle-mobile-menu" aria-label="' + (state.mobileMenuOpen ? 'Tutup menu navigasi' : 'Buka menu navigasi') + '" aria-expanded="' + (state.mobileMenuOpen ? 'true' : 'false') + '" aria-controls="kv-mobile-menu">' + (state.mobileMenuOpen ? '&times;' : '<span aria-hidden="true">&#9776;</span>') + '</button>' +
        '</div>' +
      '</div>' +
      (state.mobileMenuOpen ? '<nav id="kv-mobile-menu" class="kv-container kv-mobile-menu" aria-label="Navigasi mobile">' + linksHtml + '</nav>' : '') +
    '</header>';
  }

  function renderFooter() {
    if (state.route === 'reader' || state.route === 'admin') return '';
    return '<footer class="kv-footer">' +
      '<div class="kv-container kv-footer-inner">' +
        '<div><strong>' + escapeHtml(CONFIG.SITE_NAME) + '</strong> &middot; ' + escapeHtml(CONFIG.SITE_TAGLINE) + '</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:16px;align-items:center;">' +
          '<a href="#/tentang">Tentang</a>' +
          '<a href="#/kontak">Kontak</a>' +
          '<a href="#/privasi">Kebijakan Privasi</a>' +
          '<a href="#/ketentuan">Ketentuan</a>' +
        '</div>' +
      '</div>' +
    '</footer>';
  }

  /* =========================================================================
     HALAMAN BERANDA
     ========================================================================= */
  function renderHome() {
    var featured = state.data.manga.filter(function (m) { return m.featured; })[0] || state.data.manga[0];
    if (!featured) return '<div class="kv-container kv-section"><p>Belum ada manga tersedia.</p></div>';

    var chCount = state.data.chapters.filter(function (c) { return c.mangaId === featured.id; }).length;
    var latestCards = state.data.manga.slice()
      .sort(function (a, b) { return b.updatedAt.localeCompare(a.updatedAt); })
      .slice(0, 8).map(renderMangaCard).join('');
    var genres = collectGenres();

    /* Chapter terbaru lintas judul (maks. 6) */
    var latestChapters = state.data.chapters.slice()
      .sort(function (a, b) { return b.publishedAt.localeCompare(a.publishedAt); })
      .slice(0, 6).map(function (c) {
        var m = mangaById(c.mangaId);
        if (!m) return '';
        return '<div class="kv-chapter-row" data-action="open-reader" data-slug="' + escapeHtml(m.slug) + '" data-cid="' + escapeHtml(c.id) + '" tabindex="0" role="button" aria-label="Baca ' + escapeHtml(m.title) + ' Chapter ' + c.number + '">' +
          '<div style="display:flex;align-items:center;gap:10px;min-width:0;">' +
            kvChip('Ch. ' + c.number, true, true) +
            '<div style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"><strong>' + escapeHtml(m.title) + '</strong> <span style="color:var(--kv-text-muted);">&middot; ' + escapeHtml(c.title) + '</span></div>' +
          '</div>' +
          '<div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.8125rem;flex-shrink:0;">' + escapeHtml(c.publishedAt) + '</div>' +
        '</div>';
      }).join('');

    var popular = state.data.manga.slice().sort(function (a, b) { return b.views - a.views; }).slice(0, 4);
    var recommended = state.data.manga.filter(function (m) { return m.recommended; }).slice(0, 4);

    return '<main class="kv-container">' +
      '<section class="kv-hero" aria-label="Manga Unggulan">' +
        '<div style="display:flex;flex-direction:column;justify-content:space-between;">' +
          '<div>' +
            '<div class="kv-meta-line">' + kvChip('Pilihan Editor', true) + kvChip(featured.type) + kvChip(featured.status) + '</div>' +
            '<h1 class="kv-hero-title">' + escapeHtml(featured.title) + '</h1>' +
            '<p style="color:var(--kv-text-muted);max-width:60ch;margin:0 0 20px;">' + escapeHtml(featured.synopsis) + '</p>' +
            '<div class="kv-meta-line" style="margin-bottom:24px;">' +
              kvChip('Rating ' + featured.rating + '/5.0', false, true) + kvChip(chCount + ' Chapter', false, true) + kvChip(featured.views.toLocaleString('id-ID') + ' dibaca', false, true) +
            '</div>' +
          '</div>' +
          '<div style="display:flex;flex-wrap:wrap;gap:12px;">' +
            '<a class="kv-btn kv-btn-primary" href="#/manga/' + escapeHtml(featured.slug) + '">Baca Sekarang</a>' +
            '<a class="kv-btn kv-btn-ghost" href="#/katalog">Jelajahi Katalog</a>' +
          '</div>' +
        '</div>' +
        '<div class="kv-cover-wrap" style="max-width:280px;width:100%;justify-self:end;">' + renderCover(featured.coverBloggerUrl, featured.title) + '</div>' +
      '</section>' +
      '<section class="kv-section">' +
        '<div class="kv-section-head"><div><div class="kv-kicker">Update</div><h2 class="kv-section-title">Pembaruan Terbaru</h2></div><a href="#/katalog" style="color:var(--kv-accent);font-size:0.875rem;font-weight:600;">Lihat Semua &rarr;</a></div>' +
        '<div class="kv-grid">' + latestCards + '</div>' +
      '</section>' +
      (latestChapters
        ? '<section class="kv-section"><div class="kv-section-head"><div><div class="kv-kicker">Episode</div><h2 class="kv-section-title">Chapter Terbaru</h2></div></div><div class="kv-table-wrap">' + latestChapters + '</div></section>'
        : '') +
      '<section class="kv-section">' +
        '<div class="kv-section-head"><div><div class="kv-kicker">Populer</div><h2 class="kv-section-title">Manga Populer</h2></div><a href="#/katalog" style="color:var(--kv-accent);font-size:0.875rem;font-weight:600;">Lihat Semua &rarr;</a></div>' +
        '<div class="kv-grid">' + popular.map(renderMangaCard).join('') + '</div>' +
      '</section>' +
      '<section class="kv-section">' +
        '<div class="kv-section-head"><div><div class="kv-kicker">Kurasi</div><h2 class="kv-section-title">Rekomendasi Redaksi</h2></div></div>' +
        '<div class="kv-grid">' + recommended.map(renderMangaCard).join('') + '</div>' +
      '</section>' +
      '<section class="kv-section">' +
        '<div class="kv-section-head"><div><div class="kv-kicker">Kategori</div><h2 class="kv-section-title">Telusuri Genre</h2></div></div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:10px;">' +
          genres.map(function (g) {
            return '<button type="button" class="kv-btn kv-btn-ghost" data-action="quick-genre" data-genre="' + escapeHtml(g) + '">' + escapeHtml(g) + '</button>';
          }).join('') +
        '</div>' +
      '</section>' +
    '</main>';
  }

  function renderMangaCard(m) {
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
    var latest = chs.sort(function (a, b) { return b.number - a.number; })[0];
    return '<article class="kv-card" data-action="open-manga" data-slug="' + escapeHtml(m.slug) + '" tabindex="0" role="button" aria-label="Buka detail ' + escapeHtml(m.title) + '">' +
      '<div class="kv-cover-wrap" style="border:none;border-radius:0;">' + renderCover(m.coverBloggerUrl, m.title) + '</div>' +
      '<div class="kv-card-body">' +
        '<div class="kv-meta-line">' + kvChip(m.type, true) + kvChip(m.status) + '</div>' +
        '<h3 class="kv-card-title">' + escapeHtml(m.title) + '</h3>' +
        '<div class="kv-meta-line">' + (latest ? kvChip('Ch. ' + latest.number, false, true) + kvChip(latest.publishedAt) : kvChip('Belum ada chapter')) + '</div>' +
      '</div>' +
    '</article>';
  }

  /* =========================================================================
     HALAMAN KATALOG
     ========================================================================= */
  function renderCatalog() {
    var genreOptions = ['Semua'].concat(collectGenres());
    var typeOptions = ['Semua'].concat(collectTypes());
    var statusOptions = ['Semua', 'Ongoing', 'Tamat'];
    if (genreOptions.indexOf(state.filterGenre) === -1) state.filterGenre = 'Semua';
    if (typeOptions.indexOf(state.filterType) === -1) state.filterType = 'Semua';

    var list = state.data.manga.filter(function (m) {
      var matchQ = !state.search || m.title.toLowerCase().indexOf(state.search.toLowerCase()) !== -1;
      var matchG = state.filterGenre === 'Semua' || (m.genres || []).indexOf(state.filterGenre) !== -1;
      var matchS = state.filterStatus === 'Semua' || m.status === state.filterStatus;
      var matchT = state.filterType === 'Semua' || m.type === state.filterType;
      return matchQ && matchG && matchS && matchT;
    });

    list.sort(function (a, b) {
      if (state.sortBy === 'populer') return b.views - a.views;
      if (state.sortBy === 'abjad') return a.title.localeCompare(b.title);
      return b.updatedAt.localeCompare(a.updatedAt);
    });

    var totalPages = Math.max(1, Math.ceil(list.length / CONFIG.ITEMS_PER_PAGE));
    if (state.page > totalPages) state.page = totalPages;
    var paged = list.slice((state.page - 1) * CONFIG.ITEMS_PER_PAGE, state.page * CONFIG.ITEMS_PER_PAGE);

    var paginationHtml = '';
    if (totalPages > 1) {
      paginationHtml = '<div style="display:flex;justify-content:center;align-items:center;gap:12px;margin-top:28px;">' +
        '<button type="button" class="kv-btn kv-btn-ghost" id="kv-page-prev"' + (state.page === 1 ? ' disabled' : '') + '>&laquo; Sebelumnya</button>' +
        '<span class="kv-mono" style="color:var(--kv-text-muted);font-size:0.875rem;">Halaman ' + state.page + ' / ' + totalPages + '</span>' +
        '<button type="button" class="kv-btn kv-btn-ghost" id="kv-page-next"' + (state.page === totalPages ? ' disabled' : '') + '>Berikutnya &raquo;</button>' +
      '</div>';
    }

    return '<main class="kv-container">' +
      '<div class="kv-section-head" style="margin-top:28px;"><div><div class="kv-kicker">Koleksi</div><h1 class="kv-section-title" style="font-size:1.75rem;">Katalog Manga</h1></div><span class="kv-chip kv-mono">' + list.length + ' judul</span></div>' +
      '<div class="kv-toolbar">' +
        '<input id="kv-search-input" class="kv-input" type="search" placeholder="Cari judul manga..." value="' + escapeHtml(state.search) + '" aria-label="Cari judul manga"/>' +
        '<select id="kv-filter-genre" class="kv-select" aria-label="Filter genre">' +
          genreOptions.map(function (g) {
            return '<option value="' + escapeHtml(g) + '"' + (state.filterGenre === g ? ' selected' : '') + '>' + escapeHtml(g) + '</option>';
          }).join('') +
        '</select>' +
        '<select id="kv-filter-type" class="kv-select" aria-label="Filter tipe">' +
          typeOptions.map(function (t) {
            return '<option value="' + escapeHtml(t) + '"' + (state.filterType === t ? ' selected' : '') + '>' + escapeHtml(t) + '</option>';
          }).join('') +
        '</select>' +
        '<select id="kv-filter-status" class="kv-select" aria-label="Filter status">' +
          statusOptions.map(function (s) {
            return '<option value="' + escapeHtml(s) + '"' + (state.filterStatus === s ? ' selected' : '') + '>' + escapeHtml(s) + '</option>';
          }).join('') +
        '</select>' +
        '<select id="kv-sort-by" class="kv-select" aria-label="Urutkan">' +
          '<option value="terbaru"' + (state.sortBy === 'terbaru' ? ' selected' : '') + '>Terbaru</option>' +
          '<option value="populer"' + (state.sortBy === 'populer' ? ' selected' : '') + '>Terpopuler</option>' +
          '<option value="abjad"' + (state.sortBy === 'abjad' ? ' selected' : '') + '>A - Z</option>' +
        '</select>' +
      '</div>' +
      (paged.length === 0
        ? '<div class="kv-stat-box" style="margin-top:24px;text-align:center;"><p>Tidak ada manga yang cocok dengan filter Anda.</p></div>'
        : '<div class="kv-grid" style="margin-top:24px;">' + paged.map(renderMangaCard).join('') + '</div>') +
      paginationHtml +
    '</main>';
  }

  /* =========================================================================
     HALAMAN DETAIL MANGA
     ========================================================================= */
  function renderDetail() {
    var manga = state.data.manga.filter(function (m) { return m.slug === state.params.slug; })[0];
    if (!manga) return render404();

    var chs = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; }).slice();
    chs.sort(function (a, b) { return state.chapterSortAsc ? a.number - b.number : b.number - a.number; });
    var firstCh = chs.slice().sort(function (a, b) { return a.number - b.number; })[0];
    var isBookmarked = state.bookmarks.indexOf(manga.id) !== -1;
    var comments = state.data.comments.filter(function (c) { return c.mangaId === manga.id && c.status === 'approved'; });

    return '<main class="kv-container">' +
      '<div class="kv-detail-grid">' +
        '<div class="kv-cover-wrap">' + renderCover(manga.coverBloggerUrl, manga.title) + '</div>' +
        '<div>' +
          '<div class="kv-meta-line">' + kvChip(manga.type, true) + kvChip(manga.status) + (manga.genres || []).map(function (g) { return kvChip(g); }).join('') + '</div>' +
          '<h1 style="font-size:2rem;font-weight:800;margin:8px 0 4px;">' + escapeHtml(manga.title) + '</h1>' +
          '<div style="color:var(--kv-text-muted);font-size:0.9rem;margin-bottom:16px;">' + escapeHtml(manga.altTitle) + ' &middot; Karya ' + escapeHtml(manga.author) + '</div>' +
          '<p style="color:var(--kv-text-muted);max-width:68ch;margin:0 0 22px;">' + escapeHtml(manga.synopsis) + '</p>' +
          '<div style="display:flex;flex-wrap:wrap;gap:12px;">' +
            (firstCh ? '<a class="kv-btn kv-btn-primary" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(firstCh.id) + '">Mulai Baca Ch. ' + firstCh.number + '</a>' : '') +
            '<button type="button" class="kv-btn kv-btn-ghost" data-action="toggle-bookmark" data-id="' + escapeHtml(manga.id) + '">' + (isBookmarked ? 'Tersimpan di Favorit' : 'Ikuti / Simpan') + '</button>' +
            '<button type="button" class="kv-btn kv-btn-ghost" data-action="share-manga">Bagikan Tautan</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<section class="kv-section">' +
        '<div class="kv-section-head"><div><div class="kv-kicker">Episode</div><h2 class="kv-section-title">Daftar Chapter</h2></div><div style="display:flex;gap:10px;align-items:center;"><span class="kv-chip kv-mono">' + chs.length + '</span><button type="button" class="kv-btn kv-btn-ghost" data-action="toggle-ch-sort">' + (state.chapterSortAsc ? 'Urutan: Terlama' : 'Urutan: Terbaru') + '</button></div></div>' +
        '<div class="kv-table-wrap">' +
          chs.map(function (c) {
            return '<div class="kv-chapter-row" data-action="open-reader" data-slug="' + escapeHtml(manga.slug) + '" data-cid="' + escapeHtml(c.id) + '" tabindex="0" role="button" aria-label="Baca Chapter ' + c.number + '">' +
              '<div style="display:flex;align-items:center;gap:10px;min-width:0;">' +
                kvChip('Ch. ' + c.number, true, true) +
                '<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(c.title || '(tanpa judul)') + '</span>' +
              '</div>' +
              '<div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.8125rem;flex-shrink:0;">' + escapeHtml(c.publishedAt) + '</div>' +
            '</div>';
          }).join('') +
        '</div>' +
      '</section>' +
      '<section class="kv-section">' +
        '<div class="kv-kicker">Komunitas</div>' +
        '<h2 class="kv-section-title" style="margin-bottom:6px;">Komentar Pembaca</h2>' +
        '<p style="color:var(--kv-text-muted);font-size:0.8125rem;margin:0 0 14px;">Komentar dimoderasi admin sebelum ditampilkan publik.</p>' +
        (state.commentNotice
          ? '<div class="kv-stat-box" style="margin-bottom:14px;border-color:var(--kv-success);"><p style="margin:0;">' + escapeHtml(state.commentNotice) + '</p></div>'
          : '') +
        '<form id="kv-comment-form" data-manga-id="' + escapeHtml(manga.id) + '" style="display:flex;flex-direction:column;gap:10px;margin-bottom:20px;">' +
          '<input class="kv-input" name="author" placeholder="Nama Anda" required/>' +
          '<textarea class="kv-textarea" name="content" placeholder="Tulis ulasan atau komentar sopan..." required></textarea>' +
          '<button class="kv-btn kv-btn-primary" type="submit" style="align-self:flex-start;">Kirim Komentar</button>' +
        '</form>' +
        comments.map(function (c) {
          return '<div class="kv-stat-box" style="margin-bottom:10px;"><div style="font-weight:700;font-size:0.875rem;">' + escapeHtml(c.authorName) + ' <span class="kv-mono" style="font-weight:400;color:var(--kv-text-muted);">' + escapeHtml(c.createdAt) + '</span></div><p style="margin:6px 0 0;color:var(--kv-text-muted);">' + escapeHtml(c.content) + '</p></div>';
        }).join('') +
      '</section>' +
    '</main>';
  }

  /* =========================================================================
     READER / VIEWER
     ========================================================================= */
  function renderReader() {
    var manga = state.data.manga.filter(function (m) { return m.slug === state.params.slug; })[0];
    var chapter = state.data.chapters.filter(function (c) { return c.id === state.params.chapterId; })[0];
    if (!manga || !chapter) return render404();

    var allCh = state.data.chapters.filter(function (c) { return c.mangaId === manga.id; }).sort(function (a, b) { return a.number - b.number; });
    var idx = -1;
    for (var i = 0; i < allCh.length; i++) { if (allCh[i].id === chapter.id) idx = i; }
    var prevCh = idx > 0 ? allCh[idx - 1] : null;
    var nextCh = idx >= 0 && idx < allCh.length - 1 ? allCh[idx + 1] : null;

    saveHistory(manga.id, chapter.id, chapter.number);

    var pagesHtml = '';
    if (state.readerMode === 'vertical') {
      pagesHtml = chapter.pages.map(function (p) {
        return renderReaderPage(p, manga.title, chapter.number);
      }).join('');
    } else {
      var page = chapter.pages[state.currentPageIdx] || chapter.pages[0];
      pagesHtml = page ? renderReaderPage(page, manga.title, chapter.number) : '<p>Belum ada halaman.</p>';
      /* Arah baca RTL membalik urutan tombol navigasi halaman */
      pagesHtml += '<div class="kv-reader-page-controls" style="' + (state.readerDir === 'rtl' ? 'flex-direction:row-reverse;' : '') + '">' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="prev-page">Halaman Sebelumnya</button>' +
        '<span class="kv-mono kv-reader-page-count">' + (state.currentPageIdx + 1) + ' / ' + chapter.pages.length + '</span>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="next-page" data-max="' + chapter.pages.length + '">Halaman Berikutnya</button>' +
      '</div>';
    }

    var previousLink = prevCh
      ? '<a class="kv-reader-chapter-link" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(prevCh.id) + '"><span aria-hidden="true">&larr;</span><span class="kv-reader-link-label">Sebelumnya</span></a>'
      : '';
    var nextLink = nextCh
      ? '<a class="kv-reader-chapter-link next" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(nextCh.id) + '"><span class="kv-reader-link-label">Selanjutnya</span><span aria-hidden="true">&rarr;</span></a>'
      : '';

    return '<div class="kv-reader-app" data-theme="' + escapeHtml(state.readerTheme) + '">' +
      '<div class="kv-reader-progress" id="kv-progress-bar" style="width:0%;" aria-hidden="true"></div>' +
      '<header class="kv-reader-header">' +
        '<div class="kv-reader-top">' +
          '<div class="kv-reader-heading">' +
            '<a class="kv-reader-back" href="#/manga/' + escapeHtml(manga.slug) + '" aria-label="Kembali ke daftar chapter" title="Kembali ke daftar chapter">&larr;</a>' +
            '<div style="min-width:0;">' +
              '<span class="kv-reader-eyebrow">' + escapeHtml(CONFIG.SITE_NAME) + ' / READER</span>' +
              '<h1 class="kv-reader-title">' + escapeHtml(manga.title) + '</h1>' +
              '<p class="kv-reader-subtitle">Chapter ' + escapeHtml(chapter.number) + (chapter.title ? ' &middot; ' + escapeHtml(chapter.title) : '') + '</p>' +
            '</div>' +
          '</div>' +
          '<nav class="kv-reader-chapter-nav" aria-label="Navigasi chapter">' +
            (prevCh ? '<a class="kv-reader-chapter-link" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(prevCh.id) + '"><span aria-hidden="true">&larr;</span><span class="kv-reader-link-label">Prev</span></a>' : '') +
            (nextCh ? '<a class="kv-reader-chapter-link next" href="#/baca/' + escapeHtml(manga.slug) + '/' + escapeHtml(nextCh.id) + '"><span class="kv-reader-link-label">Next</span><span aria-hidden="true">&rarr;</span></a>' : '') +
          '</nav>' +
        '</div>' +
        '<div class="kv-reader-tools">' +
          '<span class="kv-reader-tool-label">Pengaturan baca</span>' +
          '<button type="button" class="kv-btn kv-btn-ghost" data-action="toggle-reader-mode">' + (state.readerMode === 'vertical' ? 'Mode: Vertikal' : 'Mode: Per Halaman') + '</button>' +
          '<select id="kv-reader-width" class="kv-select" aria-label="Lebar gambar"><option value="640"' + (state.readerWidth === 640 ? ' selected' : '') + '>640px</option><option value="760"' + (state.readerWidth === 760 ? ' selected' : '') + '>760px</option><option value="960"' + (state.readerWidth === 960 ? ' selected' : '') + '>960px</option></select>' +
          '<select id="kv-reader-theme" class="kv-select" aria-label="Tema reader"><option value="dark"' + (state.readerTheme === 'dark' ? ' selected' : '') + '>Gelap</option><option value="light"' + (state.readerTheme === 'light' ? ' selected' : '') + '>Terang</option><option value="sepia"' + (state.readerTheme === 'sepia' ? ' selected' : '') + '>Sepia</option></select>' +
          '<select id="kv-reader-dir" class="kv-select" aria-label="Arah membaca"><option value="ltr"' + (state.readerDir === 'ltr' ? ' selected' : '') + '>Kiri ke Kanan</option><option value="rtl"' + (state.readerDir === 'rtl' ? ' selected' : '') + '>Kanan ke Kiri</option></select>' +
        '</div>' +
      '</header>' +
      '<main class="kv-reader-stage">' +
        '<div class="kv-reader-canvas" style="max-width:' + state.readerWidth + 'px;">' +
          pagesHtml +
          (previousLink || nextLink ? '<nav class="kv-reader-end-nav" aria-label="Chapter lainnya">' + previousLink + nextLink + '</nav>' : '') +
        '</div>' +
      '</main>' +
      '</div>';
  }

  function renderReaderPage(p, title, chNum) {
    if (!p.bloggerUrl) {
      return '<div class="kv-reader-placeholder">' +
        '<div class="kv-mono" style="font-size:0.75rem;margin-bottom:8px;">HALAMAN ' + p.order + ' &middot; ' + escapeHtml(title) + ' CH.' + chNum + '</div>' +
        '<div class="kv-reader-placeholder-title">Halaman belum memiliki URL media</div>' +
        '<div class="kv-mono" style="font-size:0.75rem;">Telegram file_id: ' + escapeHtml(p.telegramFileId || '-') + '</div>' +
      '</div>';
    }
    return '<img src="' + escapeHtml(p.bloggerUrl) + '" alt="' + escapeHtml(title) + ' Chapter ' + chNum + ' Halaman ' + p.order + '" loading="lazy" referrerpolicy="no-referrer"/>';
  }

  function saveHistory(mangaId, chapterId, chapterNumber) {
    var list = state.history.filter(function (h) { return h.mangaId !== mangaId; });
    list.unshift({ mangaId: mangaId, chapterId: chapterId, chapterNumber: chapterNumber, lastReadAt: new Date().toISOString().slice(0, 10) });
    state.history = list.slice(0, 20);
    localStorage.setItem('kv_history', JSON.stringify(state.history));
  }

  /* =========================================================================
     AKUN PEMBACA & HALAMAN INFORMASI & ADMIN
     ========================================================================= */
  function renderAccount() {
    var favManga = state.data.manga.filter(function (m) { return state.bookmarks.indexOf(m.id) !== -1; });
    return '<main class="kv-container">' +
      '<h1 class="kv-section-title" style="font-size:1.75rem;margin-top:28px;">Akun &amp; Pustaka Pembaca</h1>' +
      '<div class="kv-stat-box" style="margin-top:16px;">' +
        (state.user
          ? '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;"><div><strong>' + escapeHtml(state.user.name) + '</strong><div style="color:var(--kv-text-muted);font-size:0.875rem;">' + escapeHtml(state.user.email || 'Email tidak dibagikan') + ' &middot; ' + escapeHtml(state.user.provider) + '</div><span class="kv-chip kv-chip-accent" style="margin-top:8px;">Role: ' + escapeHtml(state.user.role) + '</span></div><button type="button" class="kv-btn kv-btn-ghost" data-action="logout-user">Keluar</button></div>'
          : '<h2 style="font-size:1rem;margin:0 0 8px;">Masuk dengan akun</h2>' + renderOAuthButtons() + '<p style="font-size:0.8125rem;color:var(--kv-text-muted);margin:10px 0 0;">Pendaftaran pertama mendapatkan role admin. Akun berikutnya otomatis menjadi member.</p>') +
      '</div>' +
      '<section class="kv-section"><div class="kv-kicker">Koleksi</div><h2 class="kv-section-title">Manga Favorit (' + favManga.length + ')</h2>' +
        (favManga.length ? '<div class="kv-grid" style="margin-top:14px;">' + favManga.map(renderMangaCard).join('') + '</div>' : '<p style="color:var(--kv-text-muted);">Belum ada manga yang disimpan.</p>') +
      '</section>' +
      '<section class="kv-section"><div class="kv-kicker">Aktivitas</div><h2 class="kv-section-title">Riwayat Baca</h2>' +
        (state.history.length ? '<div class="kv-table-wrap" style="margin-top:14px;">' + state.history.map(function (h) {
          var m = state.data.manga.filter(function (x) { return x.id === h.mangaId; })[0];
          if (!m) return '';
          return '<div class="kv-chapter-row" data-action="open-reader" data-slug="' + escapeHtml(m.slug) + '" data-cid="' + escapeHtml(h.chapterId) + '" tabindex="0" role="button" aria-label="Lanjut membaca ' + escapeHtml(m.title) + ' Chapter ' + h.chapterNumber + '"><span><strong>' + escapeHtml(m.title) + '</strong> &middot; Chapter ' + h.chapterNumber + '</span><span class="kv-mono" style="color:var(--kv-text-muted);">' + escapeHtml(h.lastReadAt) + '</span></div>';
        }).join('') + '</div>' : '<p style="color:var(--kv-text-muted);">Belum ada riwayat baca.</p>') +
      '</section>' +
    '</main>';
  }

  function renderOAuthButtons() {
    if (!CONFIG.API_BASE_URL) {
      return '<p style="color:var(--kv-text-muted);font-size:0.875rem;">Login membutuhkan backend Vercel. Atur API_BASE_URL untuk mengaktifkan Google dan Discord.</p>';
    }
    return '<div style="display:flex;flex-wrap:wrap;gap:10px;">' +
      '<button type="button" class="kv-btn kv-btn-ghost" data-action="oauth-login" data-provider="google">Lanjutkan dengan Google</button>' +
      '<button type="button" class="kv-btn kv-btn-ghost" data-action="oauth-login" data-provider="discord">Lanjutkan dengan Discord</button>' +
      '</div>';
  }

  function renderAdmin() {
    if (!state.adminToken || !state.user) {
      return '<main class="kv-container" style="max-width:480px;margin-top:48px;">' +
        '<div class="kv-stat-box">' +
          '<h1 class="kv-section-title">Login Panel Admin</h1>' +
          '<p style="color:var(--kv-text-muted);font-size:0.875rem;">Gunakan Google atau Discord. Hanya akun dengan role admin yang dapat mengelola situs.</p>' +
          renderOAuthButtons() +
        '</div>' +
      '</main>';
    }
    if (state.user.role !== 'admin') {
      return '<main class="kv-container" style="max-width:560px;margin-top:48px;"><div class="kv-stat-box">' +
        '<h1 class="kv-section-title">Panel admin tidak tersedia</h1>' +
        '<p style="color:var(--kv-text-muted);">Akun ' + escapeHtml(state.user.name) + ' memiliki role <strong>member</strong>. Hanya akun pertama yang mendaftar yang menjadi admin.</p>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="logout-user">Keluar</button>' +
        '</div></main>';
    }
    var tab = state.adminTab || 'dashboard';
    var pending = state.data.comments.filter(function (c) { return c.status === 'pending'; }).length;
    var body;
     if (tab === 'manga') body = state.adminForm ? renderAdminMangaForm() : renderAdminMangaList();
     else if (tab === 'chapter') body = state.adminChapterForm ? renderAdminChapterForm() : renderAdminChapterList();
     else if (tab === 'komentar') body = renderAdminComments();
     else if (tab === 'pengguna') body = renderAdminUsers();
     else if (tab === 'pengaturan') body = renderAdminSettings();
     else body = renderAdminDashboard();

     var titles = {
       dashboard: ['Dashboard Analitik', 'KPI, grafik, dan pintasan cepat.'],
       manga: ['Manajemen Manga', 'Tambah, ubah, hapus, dan atur manga unggulan & rekomendasi.'],
       chapter: ['Manajemen Chapter', 'Atur urutan, kelola halaman, dan simpan gambar ke Telegram.'],
       komentar: ['Moderasi Komentar', 'Setujui, tolak, atau hapus komentar pembaca.'],
       pengguna: ['Manajemen Pengguna', 'Daftar akun, ubah role, dan hapus pengguna.'],
       pengaturan: ['Pengaturan', 'Konfigurasi tema, integrasi backend, dan zona bahaya.']
     };
    var t = titles[tab] || titles.dashboard;
    var topActions;
    if (tab === 'dashboard') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-new-chapter">+ Chapter</button>' +
        '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Manga</button>';
    } else if (tab === 'manga') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/katalog">Buka Katalog</a>' +
        (state.adminForm
          ? '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal Edit</button>'
          : '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Tambah Manga</button>');
    } else if (tab === 'chapter') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/katalog">Buka Katalog</a>' +
        (state.adminChapterForm
          ? '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal Edit</button>'
          : '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-chapter">+ Tambah Chapter</button>');
    } else if (tab === 'komentar') {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>';
    } else {
      topActions = '<a class="kv-btn kv-btn-ghost" href="#/">Lihat Situs</a>';
    }

     var navMain = [
       { key: 'dashboard', label: 'Dashboard', icon: 'grid' },
       { key: 'manga', label: 'Manga', icon: 'book' },
       { key: 'chapter', label: 'Chapter', icon: 'layers' },
       { key: 'komentar', label: 'Komentar', icon: 'chat', badge: pending },
       { key: 'pengguna', label: 'Pengguna', icon: 'users' },
       { key: 'pengaturan', label: 'Pengaturan', icon: 'gear' }
     ];
    var navHtml = navMain.map(function (n) {
      return '<button type="button" class="kv-admin-nav-item' + (tab === n.key ? ' active' : '') + '" role="tab" aria-selected="' + (tab === n.key ? 'true' : 'false') + '" data-action="admin-tab" data-tab="' + n.key + '">' +
        kvIcon(n.icon) + '<span>' + n.label + '</span>' +
        (n.badge ? '<span class="kv-admin-nav-badge">' + n.badge + '</span>' : '') +
      '</button>';
    }).join('');
    var quickHtml = [
      { label: 'Tambah Manga', icon: 'plus', act: 'admin-new-manga' },
      { label: 'Tambah Chapter', icon: 'layers', act: 'admin-new-chapter' },
      { label: 'Moderasi Komentar', icon: 'chat', act: 'admin-tab', tab: 'komentar' }
    ].map(function (n) {
      return '<button type="button" class="kv-admin-nav-item" data-action="' + n.act + '"' + (n.tab ? ' data-tab="' + n.tab + '"' : '') + '>' + kvIcon(n.icon) + '<span>' + n.label + '</span></button>';
    }).join('');

     return '<div class="kv-admin-shell kv-admin-top">' +
       '<header class="kv-admin-topbar kv-admin-topbar-new">' +
         '<a class="kv-admin-logo" href="#/">' + escapeHtml(CONFIG.SITE_NAME) + ' <span>Console</span></a>' +
         '<nav class="kv-admin-nav kv-admin-nav-h" aria-label="Menu panel admin">' + navHtml + '</nav>' +
         '<div class="kv-admin-top-actions">' +
           '<div class="kv-admin-chip' + (CONFIG.API_BASE_URL ? '' : ' off') + '"><span class="dot"></span><span>' + (CONFIG.API_BASE_URL ? 'Backend terhubung' : 'Mode lokal (demo)') + '</span></div>' +
           '<button type="button" class="kv-btn kv-btn-ghost" data-action="logout-admin">' + kvIcon('out') + ' Keluar</button>' +
         '</div>' +
       '</header>' +
       '<div class="kv-admin-quickbar">' +
         '<div class="kv-admin-quicklinks">' +
           '<a class="kv-admin-quicklink" href="#/">' + kvIcon('globe') + ' Lihat Situs</a>' +
           '<a class="kv-admin-quicklink" href="#/katalog">' + kvIcon('book') + ' Katalog Publik</a>' +
           '<a class="kv-admin-quicklink" href="#/akun">' + kvIcon('users') + ' Pustaka Pembaca</a>' +
           quickHtml +
         '</div>' +
       '</div>' +
       '<main class="kv-admin-main kv-admin-main-full">' +
         '<div class="kv-admin-pagehead">' +
           '<div><h1 class="kv-admin-title">' + t[0] + '</h1><p class="kv-admin-sub">' + t[1] + '</p></div>' +
           '<div class="kv-admin-top-actions">' + topActions + '</div>' +
         '</div>' +
         body +
         (state.pendingDelete ? renderConfirmModal() : '') +
       '</main>' +
     '</div>';
  }

  function renderAdminDashboard() {
    var pending = state.data.comments.filter(function (c) { return c.status === 'pending'; }).length;
    var totalViews = state.data.manga.reduce(function (acc, m) { return acc + (m.views || 0); }, 0);
    var totalUsers = (state.usersCache || []).length;
    var kpis =
      '<div class="kv-kpi"><div class="ico">' + kvIcon('book') + '</div><div class="lbl">Total Manga</div><div class="val">' + state.data.manga.length + '</div><div class="delta">Judul terdaftar</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('layers') + '</div><div class="lbl">Total Chapter</div><div class="val">' + state.data.chapters.length + '</div><div class="delta">Halaman tersimpan</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('chat') + '</div><div class="lbl">Komentar Menunggu</div><div class="val">' + pending + '</div><div class="delta">Perlu moderasi</div></div>' +
      '<div class="kv-kpi"><div class="ico">' + kvIcon('trend') + '</div><div class="lbl">Total Dibaca</div><div class="val">' + totalViews.toLocaleString('id-ID') + '</div><div class="delta">Akumulasi views</div></div>';
    // Bar chart: chapters per manga (top 8)
    var counts = state.data.manga.map(function (m) {
      return { title: m.title, count: state.data.chapters.filter(function (c) { return c.mangaId === m.id; }).length };
    }).sort(function (a, b) { return b.count - a.count; }).slice(0, 8);
    var maxC = counts.reduce(function (a, c) { return Math.max(a, c.count); }, 1) || 1;
    var bars = counts.map(function (c) {
      var h = Math.round((c.count / maxC) * 150);
      return '<div class="kv-bar-col">' +
        '<div class="kv-bar-val">' + c.count + '</div>' +
        '<div class="kv-bar" style="height:' + h + 'px;" title="' + escapeHtml(c.title) + ': ' + c.count + ' chapter"></div>' +
        '<div class="kv-bar-label">' + escapeHtml(c.title) + '</div>' +
      '</div>';
    }).join('');
    var chart = '<div class="kv-chart-card"><h3 class="kv-chart-title">Chapter per Manga</h3><p class="kv-chart-sub">Top 8 manga berdasarkan jumlah chapter.</p>' +
      (bars ? '<div class="kv-bar-chart">' + bars + '</div>' : '<p style="color:var(--kv-text-muted);">Belum ada data.</p>') + '</div>';
    var qas = [
      { icon: 'plus', t: 'Tambah Manga', d: 'Publikasikan judul baru ke katalog.', act: 'admin-new-manga' },
      { icon: 'layers', t: 'Tambah Chapter', d: 'Unggah halaman ke penyimpanan Telegram.', act: 'admin-new-chapter' },
      { icon: 'chat', t: 'Moderasi Komentar', d: pending + ' komentar menunggu review.', act: 'admin-tab', tab: 'komentar' },
      { icon: 'book', t: 'Kelola Manga', d: 'Ubah metadata, unggulan & rekomendasi.', act: 'admin-tab', tab: 'manga' },
      { icon: 'eye', t: 'Kelola Chapter', d: 'Urutan, progres gambar, dan preview.', act: 'admin-tab', tab: 'chapter' },
      { icon: 'gear', t: 'Pengaturan', d: 'Konfigurasi integrasi & data.', act: 'admin-tab', tab: 'pengaturan' }
    ].map(function (q) {
      return '<button type="button" class="kv-qa" data-action="' + q.act + '"' + (q.tab ? ' data-tab="' + q.tab + '"' : '') + '>' +
        '<span class="kv-qa-ico">' + kvIcon(q.icon) + '</span>' +
        '<span><span class="kv-qa-title">' + q.t + '</span><span class="kv-qa-desc">' + q.d + '</span></span>' +
      '</button>';
    }).join('');
    var recent = state.data.chapters.slice()
      .sort(function (a, b) { return b.publishedAt.localeCompare(a.publishedAt); })
      .slice(0, 5).map(function (c) {
        var m = mangaById(c.mangaId);
        if (!m) return '';
        return '<div class="kv-chapter-row" data-action="admin-preview-chapter" data-slug="' + escapeHtml(m.slug) + '" data-cid="' + escapeHtml(c.id) + '" tabindex="0" role="button" aria-label="Preview ' + escapeHtml(m.title) + ' Chapter ' + c.number + '">' +
          '<div><strong>' + escapeHtml(m.title) + '</strong> &middot; Chapter ' + c.number + ' <span style="color:var(--kv-text-muted);">(' + c.pages.length + ' hal.)</span></div>' +
          '<div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.8125rem;">' + escapeHtml(c.publishedAt) + '</div>' +
        '</div>';
      }).join('');
    return '<div class="kv-kpi-grid">' + kpis + '</div>' +
      '<div class="kv-two-col">' + chart +
        '<div class="kv-card"><h3>Aksi Cepat</h3><div class="kv-qa-grid">' + qas + '</div></div>' +
      '</div>' +
      '<div class="kv-card" style="margin-top:4px;">' +
        '<h3>Aktivitas Chapter Terbaru</h3>' +
        '<p class="kv-mono" style="color:var(--kv-text-muted);font-size:0.8125rem;margin:0 0 12px;">Klik untuk preview langsung di reader</p>' +
        (recent ? '<div class="kv-table-wrap">' + recent + '</div>' : '<p style="color:var(--kv-text-muted);">Belum ada chapter.</p>') +
      '</div>';
  }

  function renderAdminMangaList() {
    var q = state.adminSearch.toLowerCase();
    var list = state.data.manga.filter(function (m) {
      return !q || m.title.toLowerCase().indexOf(q) !== -1 || m.slug.indexOf(q) !== -1;
    });
    var rows = list.map(function (m) {
      var chs = state.data.chapters.filter(function (c) { return c.mangaId === m.id; });
      var expanded = state.adminExpandedManga === m.id;
      return '<tr>' +
        '<td><div style="display:flex;gap:6px;align-items:center;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-toggle-expand" data-id="' + escapeHtml(m.id) + '" aria-expanded="' + (expanded ? 'true' : 'false') + '" aria-label="Buka atau tutup daftar chapter ' + escapeHtml(m.title) + '" style="transform:' + (expanded ? 'rotate(180deg)' : 'none') + ';">' + kvIcon('chev') + '</button>' +
          '<div style="width:44px;height:58px;border-radius:6px;overflow:hidden;border:1px solid var(--kv-border);">' + renderCover(m.coverBloggerUrl, m.title) + '</div>' +
        '</div></td>' +
        '<td><strong>' + escapeHtml(m.title) + '</strong><div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.75rem;">/' + escapeHtml(m.slug) + '</div></td>' +
        '<td>' + escapeHtml(m.type) + ' &middot; ' + escapeHtml(m.status) + '</td>' +
        '<td class="kv-mono">' + chs.length + '</td>' +
        '<td>' + (m.featured ? '<span class="kv-badge kv-badge-ok">Unggulan</span> ' : '') + (m.recommended ? '<span class="kv-badge">Rekomendasi</span>' : '') + '</td>' +
        '<td><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-open-chapters" data-id="' + escapeHtml(m.id) + '">Chapter (' + chs.length + ')</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-manga" data-id="' + escapeHtml(m.id) + '">Ubah</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-manga" data-slug="' + escapeHtml(m.slug) + '">Preview</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-manga" data-id="' + escapeHtml(m.id) + '">Hapus</button>' +
        '</div></td>' +
      '</tr>' +
      (expanded ? '<tr><td colspan="6" style="padding:0;">' + renderAdminChapterPanel(m, chs) + '</td></tr>' : '');
    }).join('');
    return '<div class="kv-toolbar">' +
        '<input id="kv-admin-manga-search" class="kv-input" type="search" placeholder="Cari judul atau slug..." value="' + escapeHtml(state.adminSearch) + '" aria-label="Cari manga di panel admin"/>' +
        '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-manga">+ Tambah Manga</button>' +
      '</div>' +
      '<div class="kv-table-wrap" style="margin-top:16px;">' +
        '<table class="kv-table"><thead><tr><th>Sampul</th><th>Judul</th><th>Tipe/Status</th><th>Chapter</th><th>Penanda</th><th>Aksi</th></tr></thead><tbody>' +
        (rows || '<tr><td colspan="6" style="text-align:center;color:var(--kv-text-muted);">Tidak ada manga.</td></tr>') +
        '</tbody></table></div>';
  }

  /* Panel chapter terintegrasi di baris manga — selalu diurut otomatis by nomor */
  function renderAdminChapterPanel(m, chs) {
    var sorted = chs.slice().sort(function (a, b) { return a.number - b.number; });
    var rows = sorted.map(function (c) {
      var uploaded = c.pages.filter(function (p) { return p.bloggerUrl; }).length;
      return '<div class="kv-chapter-row" style="gap:12px;">' +
        '<div style="display:flex;align-items:center;gap:10px;min-width:0;">' +
          '<span class="kv-badge kv-mono" style="flex-shrink:0;">Ch. ' + c.number + '</span>' +
          '<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(c.title || '(tanpa judul)') + '</span>' +
          '<span class="kv-mono" style="color:var(--kv-text-muted);font-size:0.75rem;flex-shrink:0;">' + uploaded + '/' + c.pages.length + ' img</span>' +
        '</div>' +
        '<div style="display:flex;gap:6px;flex-wrap:wrap;flex-shrink:0;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-chapter" data-id="' + escapeHtml(c.id) + '">Ubah</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-chapter" data-slug="' + escapeHtml(m.slug) + '" data-cid="' + escapeHtml(c.id) + '">Preview</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-chapter" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
        '</div>' +
      '</div>';
    }).join('');
    return '<div style="background:var(--kv-surface-2);padding:14px 16px;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:10px;">' +
        '<div>' +
          '<strong style="font-size:0.875rem;">Chapter &mdash; ' + escapeHtml(m.title) + '</strong>' +
          '<div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.75rem;">' + sorted.length + ' chapter &middot; diurutkan otomatis berdasarkan nomor</div>' +
        '</div>' +
        '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-primary" data-action="admin-new-chapter" data-id="' + escapeHtml(m.id) + '">+ Tambah Chapter</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-open-chapters" data-id="' + escapeHtml(m.id) + '">Kelola Penuh</button>' +
        '</div>' +
      '</div>' +
      (rows || '<p style="color:var(--kv-text-muted);font-size:0.875rem;margin:0;">Belum ada chapter. Nomor pertama akan disarankan otomatis saat menambah.</p>') +
    '</div>';
  }

  function renderAdminMangaForm() {
    var f = state.adminForm;
    return '<form id="kv-manga-form" class="kv-stat-box" style="margin-top:16px;" novalidate>' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;">' +
        '<h2 class="kv-section-title">' + (f.id ? 'Ubah Manga' : 'Tambah Manga Baru') + '</h2>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal</button>' +
      '</div>' +
      '<input type="hidden" name="id" value="' + escapeHtml(f.id || '') + '"/>' +
      '<div class="kv-form-grid">' +
        '<label>Judul *<input class="kv-input" name="title" value="' + escapeHtml(f.title) + '" required style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Judul Alternatif<input class="kv-input" name="altTitle" value="' + escapeHtml(f.altTitle || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Slug (otomatis dari judul jika kosong)<input class="kv-input kv-mono" name="slug" value="' + escapeHtml(f.slug || '') + '" placeholder="contoh: judul-manga" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Penulis<input class="kv-input" name="author" value="' + escapeHtml(f.author || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label style="grid-column:1/-1;">Sinopsis *' +
          '<div class="kv-toolbar-wysi">' +
            '<button type="button" data-wysi="bold">B</button>' +
            '<button type="button" data-wysi="italic">I</button>' +
            '<button type="button" data-wysi="h3">H3</button>' +
            '<button type="button" data-wysi="ul">List</button>' +
            '<button type="button" data-wysi="link">Link</button>' +
          '</div>' +
          '<textarea class="kv-textarea kv-wysi-textarea" name="synopsis" id="kv-synopsis" required>' + escapeHtml(f.synopsis || '') + '</textarea>' +
        '</label>' +
        '<label style="grid-column:1/-1;">URL Cover Blogger<input class="kv-input" name="cover" value="' + escapeHtml(f.coverBloggerUrl || '') + '" placeholder="https://blogger.googleusercontent.com/..." style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Genre (pisahkan dengan koma)<input class="kv-input" name="genres" value="' + escapeHtml(f.genresText || '') + '" placeholder="Aksi, Fantasi" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<div style="display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;">' +
          '<label>Tipe<select class="kv-select" name="type">' + ['Manga', 'Manhwa', 'Manhua'].map(function (t) { return '<option value="' + t + '"' + (f.type === t ? ' selected' : '') + '>' + t + '</option>'; }).join('') + '</select></label>' +
          '<label>Status<select class="kv-select" name="status">' + ['Ongoing', 'Tamat', 'Hiatus'].map(function (s) { return '<option value="' + s + '"' + (f.status === s ? ' selected' : '') + '>' + s + '</option>'; }).join('') + '</select></label>' +
          '<label>Rating 0-5<input class="kv-input kv-mono" name="rating" type="number" step="0.1" min="0" max="5" value="' + (f.rating !== '' && f.rating != null ? f.rating : '') + '" style="width:110px;display:block;margin-top:4px;"/></label>' +
        '</div>' +
      '</div>' +
      '<div style="display:flex;gap:20px;margin:14px 0;flex-wrap:wrap;">' +
        '<label style="display:flex;align-items:center;gap:8px;"><input type="checkbox" name="featured"' + (f.featured ? ' checked' : '') + '/> Manga unggulan (banner beranda)</label>' +
        '<label style="display:flex;align-items:center;gap:8px;"><input type="checkbox" name="recommended"' + (f.recommended ? ' checked' : '') + '/> Rekomendasi redaksi</label>' +
      '</div>' +
      '<div id="kv-manga-form-err" style="color:var(--kv-danger);font-size:0.8125rem;min-height:1.2em;margin-bottom:10px;"></div>' +
      '<button class="kv-btn kv-btn-primary" type="submit">' + (f.id ? 'Simpan Perubahan' : 'Publikasikan Manga') + '</button>' +
    '</form>';
  }

  function renderAdminChapterList() {
    if (!state.data.manga.length) {
      return '<div class="kv-stat-box" style="margin-top:16px;"><p style="color:var(--kv-text-muted);margin:0;">Tambahkan manga terlebih dahulu di tab Manga sebelum mengelola chapter.</p></div>';
    }
    if (!state.adminChapterMangaId || !mangaById(state.adminChapterMangaId)) state.adminChapterMangaId = state.data.manga[0].id;
    var sel = state.adminChapterMangaId;
    var mangaSelect = '<select id="kv-ch-manga" class="kv-select" aria-label="Pilih manga">' +
      state.data.manga.map(function (m) { return '<option value="' + escapeHtml(m.id) + '"' + (m.id === sel ? ' selected' : '') + '>' + escapeHtml(m.title) + '</option>'; }).join('') +
    '</select>';
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === sel; }).sort(function (a, b) { return a.number - b.number; });
    var rows = chs.map(function (c, i) {
      var uploaded = c.pages.filter(function (p) { return p.bloggerUrl; }).length;
      return '<tr>' +
        '<td class="kv-mono"><strong>Ch. ' + c.number + '</strong></td>' +
        '<td>' + escapeHtml(c.title || '(tanpa judul)') + '</td>' +
        '<td class="kv-mono">' + escapeHtml(c.publishedAt) + '</td>' +
        '<td class="kv-mono">' + uploaded + '/' + c.pages.length + ' halaman siap baca</td>' +
        '<td><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-move-chapter" data-mid="' + escapeHtml(sel) + '" data-id="' + escapeHtml(c.id) + '" data-dir="up"' + (i === 0 ? ' disabled' : '') + ' aria-label="Naikkan urutan chapter">Naik</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-move-chapter" data-mid="' + escapeHtml(sel) + '" data-id="' + escapeHtml(c.id) + '" data-dir="down"' + (i === chs.length - 1 ? ' disabled' : '') + ' aria-label="Turunkan urutan chapter">Turun</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-edit-chapter" data-id="' + escapeHtml(c.id) + '">Ubah</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-preview-chapter" data-slug="' + escapeHtml((mangaById(sel) || {}).slug || '') + '" data-cid="' + escapeHtml(c.id) + '">Preview</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-chapter" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
        '</div></td>' +
      '</tr>';
    }).join('');
    return '<div class="kv-toolbar">' +
        mangaSelect +
        '<button type="button" class="kv-btn kv-btn-primary" data-action="admin-new-chapter">+ Tambah Chapter</button>' +
      '</div>' +
      '<div class="kv-table-wrap" style="margin-top:16px;">' +
        '<table class="kv-table"><thead><tr><th>No.</th><th>Judul</th><th>Tanggal</th><th>Progres Gambar</th><th>Aksi</th></tr></thead><tbody>' +
        (rows || '<tr><td colspan="5" style="text-align:center;color:var(--kv-text-muted);">Belum ada chapter untuk manga ini.</td></tr>') +
        '</tbody></table></div>';
  }

  function renderAdminChapterForm() {
    var f = state.adminChapterForm;
    f.pages = f.pages || [];
    var pagesRows = f.pages.map(function (p, i) {
      return '<tr>' +
        '<td class="kv-mono">' + (i + 1) + '</td>' +
        '<td>' + (p.bloggerUrl
          ? '<img class="kv-page-thumb" src="' + escapeHtml(p.bloggerUrl) + '" alt="Preview halaman ' + (i + 1) + '"/>'
          : '<div class="kv-page-thumb" style="display:flex;align-items:center;justify-content:center;font-size:0.625rem;color:var(--kv-text-muted);">' + (p.telegramFileId ? 'TG OK' : '-') + '</div>') + '</td>' +
        '<td class="kv-mono" style="font-size:0.75rem;">' + escapeHtml(p.fileName) +
          '<div style="color:var(--kv-text-muted);">' + escapeHtml(p.status || '-') + '<br/>TG: ' + escapeHtml(p.telegramFileId ? String(p.telegramFileId).slice(0, 16) + '...' : '-') + ' &middot; Proxy: ' + (p.bloggerUrl ? 'OK' : '-') + '</div></td>' +
        '<td><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-page-move" data-idx="' + i + '" data-dir="up"' + (i === 0 ? ' disabled' : '') + ' aria-label="Naikkan urutan halaman">Naik</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-page-move" data-idx="' + i + '" data-dir="down"' + (i === f.pages.length - 1 ? ' disabled' : '') + ' aria-label="Turunkan urutan halaman">Turun</button>' +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-page-remove" data-idx="' + i + '">Hapus</button>' +
        '</div></td>' +
      '</tr>';
    }).join('');
    return '<form id="kv-chapter-form" class="kv-stat-box" style="margin-top:16px;" novalidate>' +
      '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;">' +
        '<h2 class="kv-section-title">' + (f.id ? 'Ubah Chapter' : 'Tambah Chapter Baru') + '</h2>' +
        '<button type="button" class="kv-btn kv-btn-ghost" data-action="admin-cancel-form">Batal</button>' +
      '</div>' +
      '<input type="hidden" name="id" value="' + escapeHtml(f.id || '') + '"/>' +
      '<div class="kv-form-grid">' +
        '<label>Manga *<select class="kv-select" name="mangaId" id="kv-ch-form-manga" style="width:100%;display:block;margin-top:4px;">' +
          state.data.manga.map(function (m) { return '<option value="' + escapeHtml(m.id) + '"' + (m.id === f.mangaId ? ' selected' : '') + '>' + escapeHtml(m.title) + '</option>'; }).join('') +
        '</select></label>' +
        '<label>Nomor Chapter *<input class="kv-input kv-mono" name="number" type="number" min="1" step="1" value="' + escapeHtml(f.number) + '" required style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Judul Chapter<input class="kv-input" name="title" value="' + escapeHtml(f.title || '') + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
        '<label>Tanggal Publikasi<input class="kv-input kv-mono" name="publishedAt" type="date" value="' + escapeHtml(f.publishedAt || today()) + '" style="width:100%;display:block;margin-top:4px;"/></label>' +
      '</div>' +
      '<div style="margin:16px 0 8px;">' +
        '<h3 style="margin:0 0 8px;font-size:0.9375rem;">Halaman Gambar (Penyimpanan Telegram)</h3>' +
        '<div id="kv-dropzone" class="kv-dropzone" tabindex="0" role="button" aria-label="Seret gambar ke sini atau klik untuk memilih">' +
          '<div class="ico">📁</div>' +
          '<div><strong>Seret gambar ke sini</strong> atau klik untuk memilih</div>' +
          '<div style="font-size:.75rem;margin-top:4px;">JPEG/PNG/WebP, maks 3 MiB per berkas</div>' +
        '</div>' +
        '<input id="kv-ch-files" type="file" accept="image/jpeg,image/png,image/webp" multiple class="kv-input" style="display:none;"/>' +
        '<p style="color:var(--kv-text-muted);font-size:0.75rem;margin:6px 0 0;">Setiap file dikirim ke Vercel <code>/api/admin/upload-dual</code> dan disimpan sebagai dokumen Telegram. Reader menayangkan gambar melalui endpoint proxy Vercel. Batas 3 MiB per berkas.</p>' +
      '</div>' +
      (f.pages.length
        ? '<div class="kv-table-wrap" style="margin-top:12px;"><table class="kv-table"><thead><tr><th>Urut</th><th>Preview</th><th>Berkas &amp; Status</th><th>Aksi</th></tr></thead><tbody>' + pagesRows + '</tbody></table></div>'
        : '<p style="color:var(--kv-text-muted);font-size:0.875rem;">Belum ada halaman. Pilih satu atau beberapa gambar sekaligus.</p>') +
      '<div id="kv-chapter-form-err" style="color:var(--kv-danger);font-size:0.8125rem;min-height:1.2em;margin:12px 0 10px;"></div>' +
      '<button class="kv-btn kv-btn-primary" type="submit">' + (f.id ? 'Simpan Perubahan' : 'Publikasikan Chapter') + '</button>' +
    '</form>';
  }

  function renderAdminComments() {
    var opts = [['Semua', 'Semua'], ['pending', 'Menunggu'], ['approved', 'Disetujui'], ['rejected', 'Ditolak']];
    var list = state.data.comments.filter(function (c) { return state.commentFilter === 'Semua' || c.status === state.commentFilter; });
    var rows = list.map(function (c) {
      var m = mangaById(c.mangaId);
      var badge = c.status === 'approved' ? '<span class="kv-badge kv-badge-ok">Disetujui</span>'
        : c.status === 'pending' ? '<span class="kv-badge kv-badge-pending">Menunggu</span>'
        : '<span class="kv-badge kv-badge-reject">Ditolak</span>';
      return '<tr>' +
        '<td>' + escapeHtml(m ? m.title : '(manga dihapus)') + '</td>' +
        '<td><strong>' + escapeHtml(c.authorName) + '</strong><div class="kv-mono" style="color:var(--kv-text-muted);font-size:0.75rem;">' + escapeHtml(c.createdAt) + '</div></td>' +
        '<td style="max-width:280px;">' + escapeHtml(c.content) + '</td>' +
        '<td>' + badge + '</td>' +
        '<td><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
          (c.status !== 'approved' ? '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-set-comment" data-id="' + escapeHtml(c.id) + '" data-status="approved">Setujui</button>' : '') +
          (c.status !== 'rejected' ? '<button type="button" class="kv-btn kv-btn-sm kv-btn-ghost" data-action="admin-set-comment" data-id="' + escapeHtml(c.id) + '" data-status="rejected">Tolak</button>' : '') +
          '<button type="button" class="kv-btn kv-btn-sm kv-btn-danger-ghost" data-action="admin-delete-comment" data-id="' + escapeHtml(c.id) + '">Hapus</button>' +
        '</div></td>' +
      '</tr>';
    }).join('');
    return '<div class="kv-toolbar">' +
        '<select id="kv-comment-filter" class="kv-select" aria-label="Filter status komentar">' +
          opts.map(function (o) { return '<option value="' + o[0] + '"' + (state.commentFilter === o[0] ? ' selected' : '') + '>' + o[1] + '</option>'; }).join('') +
        '</select>' +
      '</div>' +
      '<div class="kv-table-wrap" style="margin-top:16px;">' +
        '<table class="kv-table"><thead><tr><th>Manga</th><th>Penulis</th><th>Isi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>' +
        (rows || '<tr><td colspan="5" style="text-align:center;color:var(--kv-text-muted);">Tidak ada komentar.</td></tr>') +
        '</tbody></table></div>';
  }

  function loadAdminUsers() {
    if (!CONFIG.API_BASE_URL || !state.adminToken) return;
    fetch(CONFIG.API_BASE_URL + '/api/admin/users', { headers: { 'Authorization': 'Bearer ' + state.adminToken } })
      .then(function (r) { if (!r.ok) throw new Error('Gagal memuat pengguna.'); return r.json(); })
      .then(function (res) { state.usersCache = res.users || []; render(); })
      .catch(function () { state.usersCache = []; });
  }

  function renderAdminUsers() {
    if (state.usersCache === undefined) { state.usersCache = null; loadAdminUsers(); }
    if (state.usersCache === null) return '<div class="kv-card"><p style="color:var(--kv-text-muted);">Memuat pengguna...</p></div>';
    var rows = state.usersCache.map(function (u) {
      var isSelf = state.user && state.user.id === u.id;
      return '<tr>' +
        '<td><img src="' + escapeHtml(u.avatar || 'https://api.dicebear.com/7.x/initials/svg?seed=' + encodeURIComponent(u.name)) + '" alt=""/>' + escapeHtml(u.name) + (isSelf ? ' <span style="color:var(--kv-text-muted);font-size:.75rem;">(Anda)</span>' : '') + '</td>' +
        '<td>' + escapeHtml(u.email || '-') + '</td>' +
        '<td>' + escapeHtml(u.provider || '-') + '</td>' +
        '<td><span class="kv-role-badge ' + escapeHtml(u.role) + '">' + escapeHtml(u.role) + '</span></td>' +
        '<td class="kv-mono" style="font-size:.75rem;">' + escapeHtml(u.createdAt || '-') + '</td>' +
        '<td><select class="kv-input" style="width:auto;padding:4px 8px;" data-action="admin-user-role" data-id="' + escapeHtml(u.id) + '">' +
          '<option value="member"' + (u.role === 'member' ? ' selected' : '') + '>member</option>' +
          '<option value="admin"' + (u.role === 'admin' ? ' selected' : '') + '>admin</option>' +
        '</select>' +
        (isSelf ? '' : '<button type="button" class="kv-btn kv-btn-ghost" style="margin-left:6px;" data-action="admin-delete-user" data-id="' + escapeHtml(u.id) + '">Hapus</button>') +
      '</tr>';
    }).join('');
    return '<div class="kv-card"><h3>Daftar Pengguna (' + state.usersCache.length + ')</h3>' +
      '<div class="kv-table-wrap"><table class="kv-table"><thead><tr><th>Nama</th><th>Email</th><th>Provider</th><th>Role</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody>' +
      (rows || '<tr><td colspan="6" style="text-align:center;color:var(--kv-text-muted);">Belum ada pengguna.</td></tr>') +
      '</tbody></table></div></div>';
  }

  function changeUserRoleAdmin(userId, role) {
    if (!CONFIG.API_BASE_URL || !state.adminToken) { alert('Backend tidak terhubung.'); return; }
    fetch(CONFIG.API_BASE_URL + '/api/admin/user-role', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
      body: JSON.stringify({ id: userId, role: role })
    }).then(function (r) {
      return r.json().then(function (j) { return { ok: r.ok, status: r.status, body: j }; });
    }).then(function (res) {
      if (res.ok) {
        if (state.usersCache) {
          state.usersCache = state.usersCache.map(function (u) { if (u.id === userId) { u.role = role; } return u; });
        }
        alert('Role berhasil diubah menjadi ' + role + '.');
      } else {
        alert('Gagal: ' + (res.body && res.body.error ? res.body.error : ('HTTP ' + res.status)));
      }
      state.usersCache = undefined;
      loadAdminUsers();
    }).catch(function (e) { alert('Error jaringan: ' + e.message); });
  }
  function deleteUserAdmin(userId) {
    if (!confirm('Hapus pengguna ini?')) return;
    if (!CONFIG.API_BASE_URL || !state.adminToken) { toast('Backend tidak terhubung.', 'error'); return; }
    fetch(CONFIG.API_BASE_URL + '/api/admin/delete-user', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
      body: JSON.stringify({ id: userId })
    }).then(function (r) { if (!r.ok) return r.json().then(function (j) { throw new Error(j.error || 'Gagal menghapus pengguna.'); }); return r.json(); })
      .then(function () { toast('Pengguna dihapus.', 'success'); state.usersCache = undefined; loadAdminUsers(); })
      .catch(function (e) { toast(e.message, 'error'); });
  }

