  function blankManga() {
    return { id: '', slug: '', title: '', altTitle: '', author: '', synopsis: '', coverBloggerUrl: '', genresText: '', type: 'Manga', status: 'Ongoing', rating: '', featured: false, recommended: false };
  }

  function blankChapter(mid) {
    var m = mid ? mangaById(mid) : state.data.manga[0];
    var mangaId = m ? m.id : '';
    var num = 1;
    state.data.chapters.filter(function (c) { return c.mangaId === mangaId; }).forEach(function (c) { if (c.number >= num) num = c.number + 1; });
    return { id: '', mangaId: mangaId, number: num, title: '', publishedAt: today(), pages: [] };
  }

  function saveMangaForm(form) {
    var err = document.getElementById('kv-manga-form-err');
    var fd = new FormData(form);
    var title = String(fd.get('title') || '').trim();
    var synopsis = String(fd.get('synopsis') || '').trim();
    var slug = slugify(fd.get('slug') || title);
    var rating = parseFloat(fd.get('rating'));
    var problems = [];
    if (title.length < 2) problems.push('Judul minimal 2 karakter.');
    if (synopsis.length < 10) problems.push('Sinopsis minimal 10 karakter.');
    if (!slug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) problems.push('Slug hanya boleh huruf kecil, angka, dan tanda hubung.');
    if (state.data.manga.filter(function (m) { return m.slug === slug && m.id !== (fd.get('id') || ''); }).length) problems.push('Slug sudah dipakai manga lain.');
    if (!isNaN(rating) && (rating < 0 || rating > 5)) problems.push('Rating harus antara 0 dan 5.');
    if (isNaN(rating)) rating = 0;
    if (problems.length) { if (err) err.textContent = problems.join(' '); return; }

    var genres = String(fd.get('genres') || '').split(',').map(function (g) { return g.trim(); }).filter(Boolean);
    var existing = mangaById(fd.get('id') || '');
    var obj = {
      id: existing ? existing.id : uid('mng'),
      slug: slug,
      title: title,
      altTitle: String(fd.get('altTitle') || '').trim(),
      author: String(fd.get('author') || '').trim(),
      synopsis: synopsis,
      coverBloggerUrl: String(fd.get('cover') || '').trim(),
      genres: genres,
      type: fd.get('type'),
      status: fd.get('status'),
      rating: rating,
      featured: fd.get('featured') === 'on',
      recommended: fd.get('recommended') === 'on',
      views: existing ? existing.views : 0,
      updatedAt: today()
    };
    if (existing) {
      state.data.manga = state.data.manga.map(function (m) { return m.id === obj.id ? obj : m; });
    } else {
      state.data.manga.push(obj);
    }
    persistData();
    apiSync('/api/admin/save-manga', obj);
    toast(existing ? 'Perubahan manga disimpan.' : 'Manga baru dipublikasikan.', 'ok');
    state.adminForm = null;
    render();
  }

  function saveChapterForm(form) {
    var err = document.getElementById('kv-chapter-form-err');
    var fd = new FormData(form);
    var mangaId = fd.get('mangaId');
    var number = parseInt(fd.get('number'), 10);
    var title = String(fd.get('title') || '').trim();
    var publishedAt = fd.get('publishedAt') || today();
    var pages = state.adminChapterForm.pages || [];
    var problems = [];
    if (!mangaId) problems.push('Pilih manga terlebih dahulu.');
    if (isNaN(number) || number < 1) problems.push('Nomor chapter harus angka >= 1.');
    if (state.data.chapters.filter(function (c) { return c.mangaId === mangaId && c.number === number && c.id !== (fd.get('id') || ''); }).length) problems.push('Nomor chapter tersebut sudah dipakai di manga ini.');
    if (problems.length) { if (err) err.textContent = problems.join(' '); return; }

    var existing = chapterById(fd.get('id') || '');
    var obj = { id: existing ? existing.id : uid('ch'), mangaId: mangaId, number: number, title: title, publishedAt: publishedAt, pages: pages };
    if (existing) {
      state.data.chapters = state.data.chapters.map(function (c) { return c.id === obj.id ? obj : c; });
    } else {
      state.data.chapters.push(obj);
    }
    var m = mangaById(mangaId);
    if (m) m.updatedAt = today();
    persistData();
    apiSync('/api/admin/save-chapter', obj);
    toast(existing ? 'Perubahan chapter disimpan.' : 'Chapter dipublikasikan.', 'ok');
    state.adminChapterForm = null;
    state.adminChapterMangaId = mangaId;
    state.adminExpandedManga = mangaId;
    render();
  }

  function moveChapter(mid, chId, dir) {
    var chs = state.data.chapters.filter(function (c) { return c.mangaId === mid; }).sort(function (a, b) { return a.number - b.number; });
    var i = -1;
    chs.forEach(function (c, idx) { if (c.id === chId) i = idx; });
    var j = dir === 'up' ? i - 1 : i + 1;
    if (i === -1 || j < 0 || j >= chs.length) return;
    var tmp = chs[i].number;
    chs[i].number = chs[j].number;
    chs[j].number = tmp;
    persistData();
    apiSync('/api/admin/save-chapter', chs[i]);
    apiSync('/api/admin/save-chapter', chs[j]);
    render();
  }

  function movePage(idx, dir) {
    var f = state.adminChapterForm;
    if (!f) return;
    var j = dir === 'up' ? idx - 1 : idx + 1;
    if (j < 0 || j >= f.pages.length) return;
    var tmp = f.pages[idx]; f.pages[idx] = f.pages[j]; f.pages[j] = tmp;
    reindexPages();
    render();
  }

  function removePage(idx) {
    var f = state.adminChapterForm;
    if (!f) return;
    f.pages.splice(idx, 1);
    reindexPages();
    render();
  }

  function reindexPages() {
    var f = state.adminChapterForm;
    if (!f) return;
    f.pages.forEach(function (p, i) { p.order = i + 1; });
  }

  function setCommentStatus(id, status) {
    var c = state.data.comments.filter(function (x) { return x.id === id; })[0];
    if (!c) return;
    c.status = status;
    persistData();
    apiSync('/api/admin/comment-status', { id: id, status: status });
    toast(status === 'approved' ? 'Komentar disetujui & tampil publik.' : 'Komentar ditolak.', 'ok');
    render();
  }

  function performConfirmedDelete() {
    var d = state.pendingDelete;
    state.pendingDelete = null;
    if (!d) { render(); return; }
    if (d.type === 'manga') {
      state.adminExpandedManga = null;
      state.data.manga = state.data.manga.filter(function (m) { return m.id !== d.id; });
      state.data.chapters = state.data.chapters.filter(function (c) { return c.mangaId !== d.id; });
      state.data.comments = state.data.comments.filter(function (c) { return c.mangaId !== d.id; });
      toast('Manga beserta chapter & komentarnya dihapus.', 'ok');
      apiSync('/api/admin/delete-manga', { id: d.id });
      persistData();
    } else if (d.type === 'chapter') {
      state.data.chapters = state.data.chapters.filter(function (c) { return c.id !== d.id; });
      toast('Chapter dihapus.', 'ok');
      apiSync('/api/admin/delete-chapter', { id: d.id });
      persistData();
    } else if (d.type === 'comment') {
      state.data.comments = state.data.comments.filter(function (c) { return c.id !== d.id; });
      toast('Komentar dihapus.', 'ok');
      apiSync('/api/admin/delete-comment', { id: d.id });
      persistData();
    } else if (d.type === 'reset') {
      localStorage.removeItem('kv_local_data');
      state.data = JSON.parse(JSON.stringify(SAMPLE_DATA));
      toast('Data lokal dikembalikan ke data contoh.', 'ok');
    }
    render();
  }

  /* Unggah satu berkas per request; gambar disimpan di Telegram dan
     ditayangkan oleh URL proxy Vercel. */
  function uploadPageFiles(files) {
    var f = state.adminChapterForm;
    if (!f) return;
    Array.prototype.forEach.call(files, function (file) {
      var page = { order: f.pages.length + 1, fileName: file.name, bloggerUrl: '', telegramFileId: '', status: 'menunggu unggah' };
      f.pages.push(page);
      if (file.size > 3 * 1024 * 1024) {
        page.status = 'gagal: ukuran maksimal 3 MiB';
        toast('Ukuran ' + file.name + ' melebihi batas 3 MiB untuk backend Vercel.', 'err');
        render();
        return;
      }
      render();
      if (!CONFIG.API_BASE_URL) {
        page.status = 'siap (mode lokal - proxy belum diatur)';
        render();
        return;
      }
      page.status = 'mengunggah ke proxy...';
      render();
      var fr = new FileReader();
      fr.onload = function () {
        fetch(CONFIG.API_BASE_URL + '/api/admin/upload-dual', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + state.adminToken },
          body: JSON.stringify({ fileName: file.name, mimeType: file.type, dataBase64: fr.result })
        }).then(function (r) {
          return r.json().then(function (res) {
            if (!r.ok) throw new Error(res.error || 'HTTP ' + r.status);
            return res;
          });
        }).then(function (res) {
          page.telegramFileId = (res && res.telegramFileId) || '';
          page.bloggerUrl = (res && res.bloggerUrl) || '';
          page.status = 'Telegram: ' + ((res && res.telegramStatus) || 'gagal') + ' | Proxy: ' + ((res && res.bloggerStatus) || 'gagal');
          if (!page.bloggerUrl || !page.telegramFileId) {
            toast('Sebagian tujuan gagal untuk ' + file.name + ' - periksa status lalu unggah ulang.', 'warn');
          }
          render();
        }).catch(function (err) {
          page.status = 'gagal: ' + err.message;
          toast('Gagal mengunggah ' + file.name + ': ' + err.message, 'err');
          render();
        });
      };
      fr.readAsDataURL(file);
    });
  }

  function renderInfo() {
    var p = state.params.page;
    var titles = { tentang: 'Tentang ' + CONFIG.SITE_NAME, kontak: 'Kontak Redaksi', privasi: 'Kebijakan Privasi', ketentuan: 'Ketentuan Penggunaan' };
    return '<main class="kv-container" style="max-width:760px;margin-top:32px;">' +
      '<h1 style="font-size:1.75rem;font-weight:800;">' + escapeHtml(titles[p] || 'Informasi') + '</h1>' +
      '<div class="kv-stat-box" style="margin-top:16px;">' +
        '<p>' + escapeHtml(CONFIG.SITE_NAME) + ' dibangun dengan antarmuka Blogger yang ringan, katalog dan media tersimpan di Telegram melalui backend Vercel.</p>' +
        '<p>Hubungi kami melalui: <strong>' + escapeHtml(CONFIG.CONTACT_EMAIL) + '</strong></p>' +
      '</div>' +
    '</main>';
  }

  function render404() {
    return '<main class="kv-container" style="text-align:center;margin-top:64px;">' +
      '<div class="kv-mono kv-404" style="font-size:3rem;font-weight:800;color:var(--kv-accent);">404</div>' +
      '<h1>Halaman Tidak Ditemukan</h1>' +
      '<p style="color:var(--kv-text-muted);">Tautan manga atau chapter yang Anda tuju tidak tersedia.</p>' +
      '<a class="kv-btn kv-btn-primary" href="#/">Kembali ke Beranda</a>' +
    '</main>';
  }

  /* =========================================================================
     RENDER UTAMA & EVENT HANDLERS
     ========================================================================= */
  function render() {
    var app = document.getElementById('kv-app');
    if (!app) return;
    var bodyHtml = '';
    if (state.loading) {
      bodyHtml = '<div class="kv-container" style="margin-top:40px;"><div class="kv-stat-box">Memuat katalog manga...</div></div>';
    } else if (state.error) {
      bodyHtml = '<div class="kv-container" style="margin-top:40px;"><div class="kv-stat-box"><strong>Terjadi Kesalahan:</strong> ' + escapeHtml(state.error) + '<div style="margin-top:12px;"><button type="button" class="kv-btn kv-btn-ghost" data-action="retry-api">Coba Lagi</button></div></div></div>';
    } else {
      if (state.route === 'home') bodyHtml = renderHome();
      else if (state.route === 'catalog') bodyHtml = renderCatalog();
      else if (state.route === 'detail') bodyHtml = renderDetail();
      else if (state.route === 'reader') bodyHtml = renderReader();
      else if (state.route === 'account') bodyHtml = renderAccount();
      else if (state.route === 'admin') bodyHtml = renderAdmin();
      else if (state.route === 'info') bodyHtml = renderInfo();
      else bodyHtml = render404();
    }
    app.innerHTML = renderHeader() + bodyHtml + renderFooter();
    bindEvents();
  }

  function bindEvents() {
    var sInput = document.getElementById('kv-search-input');
    if (sInput) sInput.oninput = function (e) { state.search = e.target.value; state.page = 1; state.refocusSearch = true; render(); };
    // Pertahankan fokus kursor di kolom pencarian setelah render ulang
    if (sInput && state.refocusSearch) {
      state.refocusSearch = false;
      sInput.focus();
      var len = sInput.value.length;
      sInput.setSelectionRange(len, len);
    }
    var fGenre = document.getElementById('kv-filter-genre');
    if (fGenre) fGenre.onchange = function (e) { state.filterGenre = e.target.value; state.page = 1; render(); };
    var fType = document.getElementById('kv-filter-type');
    if (fType) fType.onchange = function (e) { state.filterType = e.target.value; state.page = 1; render(); };
    var pPrev = document.getElementById('kv-page-prev');
    if (pPrev) pPrev.onclick = function () { if (state.page > 1) { state.page--; render(); window.scrollTo(0, 0); } };
    var pNext = document.getElementById('kv-page-next');
    if (pNext) pNext.onclick = function () { state.page++; render(); window.scrollTo(0, 0); };
    var fStatus = document.getElementById('kv-filter-status');
    if (fStatus) fStatus.onchange = function (e) { state.filterStatus = e.target.value; state.page = 1; render(); };
    var sortBy = document.getElementById('kv-sort-by');
    if (sortBy) sortBy.onchange = function (e) { state.sortBy = e.target.value; render(); };
    var rWidth = document.getElementById('kv-reader-width');
    if (rWidth) rWidth.onchange = function (e) { state.readerWidth = Number(e.target.value); render(); };
    var rTheme = document.getElementById('kv-reader-theme');
    if (rTheme) rTheme.onchange = function (e) { state.readerTheme = e.target.value; render(); };
    var rDir = document.getElementById('kv-reader-dir');
    if (rDir) rDir.onchange = function (e) { state.readerDir = e.target.value; render(); };

    var cForm = document.getElementById('kv-comment-form');
    if (cForm) {
      cForm.onsubmit = function (e) {
        e.preventDefault();
        var fd = new FormData(cForm);
        var mangaId = cForm.getAttribute('data-manga-id');
        state.data.comments.unshift({
          id: 'c-' + Date.now(),
          mangaId: mangaId,
          authorName: fd.get('author'),
          content: fd.get('content'),
          createdAt: new Date().toISOString().slice(0, 10),
          status: 'pending'
        });
        persistData();
        state.commentNotice = 'Komentar Anda terkirim dan menunggu moderasi admin. Terima kasih!';
        if (CONFIG.API_BASE_URL) {
          fetch(CONFIG.API_BASE_URL + '/api/comment', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ mangaId: mangaId, authorName: fd.get('author'), content: fd.get('content') })
          }).catch(function () { toast('Komentar tersimpan lokal, gagal terkirim ke server.', 'warn'); });
        }
        render();
      };
    }

    /* --- Binding panel admin --- */
    var aSearch = document.getElementById('kv-admin-manga-search');
    if (aSearch) aSearch.oninput = function (e) { state.adminSearch = e.target.value; state.adminRefocusSearch = true; render(); };
    if (aSearch && state.adminRefocusSearch) {
      state.adminRefocusSearch = false;
      aSearch.focus();
      var aLen = aSearch.value.length;
      aSearch.setSelectionRange(aLen, aLen);
    }
     var mForm = document.getElementById('kv-manga-form');
     if (mForm) mForm.onsubmit = function (e) { e.preventDefault(); saveMangaForm(mForm); };
     document.querySelectorAll('[data-wysi]').forEach(function (btn) {
       btn.onclick = function () {
         var ta = document.getElementById('kv-synopsis');
         if (!ta) return;
         var tag = btn.getAttribute('data-wysi');
         var start = ta.selectionStart, end = ta.selectionEnd;
         var sel = ta.value.slice(start, end);
         var wrap = { bold: ['**', '**'], italic: ['*', '*'], h3: ['### ', ''], ul: ['- ', ''], link: ['[', '](url)'] }[tag];
         if (!wrap) return;
         var text = wrap[0] + (sel || 'teks') + wrap[1];
         ta.value = ta.value.slice(0, start) + text + ta.value.slice(end);
         ta.focus();
         ta.selectionStart = start + wrap[0].length;
         ta.selectionEnd = start + wrap[0].length + (sel || 'teks').length;
       };
     });
    var chMangaSel = document.getElementById('kv-ch-manga');
    if (chMangaSel) chMangaSel.onchange = function (e) { state.adminChapterMangaId = e.target.value; render(); };
    var chForm = document.getElementById('kv-chapter-form');
    if (chForm) chForm.onsubmit = function (e) { e.preventDefault(); saveChapterForm(chForm); };
    var chFormSel = document.getElementById('kv-ch-form-manga');
    if (chFormSel) chFormSel.onchange = function (e) { if (state.adminChapterForm) state.adminChapterForm.mangaId = e.target.value; };
     var chFiles = document.getElementById('kv-ch-files');
     if (chFiles) chFiles.onchange = function (e) {
       var files = Array.prototype.slice.call(e.target.files);
       e.target.value = '';
       if (files.length) uploadPageFiles(files);
     };
     var dropzone = document.getElementById('kv-dropzone');
     if (dropzone) {
       dropzone.onclick = function () { if (chFiles) chFiles.click(); };
       dropzone.ondragover = function (e) { e.preventDefault(); dropzone.classList.add('drag'); };
       dropzone.ondragleave = function () { dropzone.classList.remove('drag'); };
       dropzone.ondrop = function (e) {
         e.preventDefault();
         dropzone.classList.remove('drag');
         var files = [];
         if (e.dataTransfer && e.dataTransfer.files) files = Array.prototype.slice.call(e.dataTransfer.files);
         if (files.length) uploadPageFiles(files);
       };
     }
     var cFilter = document.getElementById('kv-comment-filter');
     if (cFilter) cFilter.onchange = function (e) { state.commentFilter = e.target.value; render(); };
     if (!window.__adminChangeDelegated) {
       window.__adminChangeDelegated = true;
       document.addEventListener('change', function (e) {
         var sel = e.target && e.target.closest ? e.target.closest('select[data-action="admin-user-role"]') : null;
         if (sel) changeUserRoleAdmin(sel.getAttribute('data-id'), sel.value);
       });
     }
  }

  document.addEventListener('click', function (e) {
    var routeLink = e.target.closest('a[href^="/"], a[href^="#/"]');
    if (!routeLink || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    e.preventDefault();
    navigate(routeLink.getAttribute('href'));
  });

  document.addEventListener('click', function (e) {
    var el = e.target.closest('[data-action]');
    if (!el) return;
    var act = el.getAttribute('data-action');
    if (act === 'toggle-theme') { state.theme = state.theme === 'dark' ? 'light' : 'dark'; applyTheme(); render(); }
    else if (act === 'oauth-login') {
      if (!CONFIG.API_BASE_URL) { toast('Backend Vercel belum dikonfigurasi.', 'warn'); return; }
      var provider = el.getAttribute('data-provider');
      if (provider !== 'google' && provider !== 'discord') return;
      var returnOrigin = window.location.origin;
      window.location.assign(CONFIG.API_BASE_URL + '/api/auth/' + provider + '/start?return_to=' + encodeURIComponent(returnOrigin));
    }
    else if (act === 'toggle-mobile-menu') { state.mobileMenuOpen = !state.mobileMenuOpen; render(); }
    else if (act === 'open-manga') { navigate('#/manga/' + el.getAttribute('data-slug')); }
    else if (act === 'open-reader') { navigate('#/baca/' + el.getAttribute('data-slug') + '/' + el.getAttribute('data-cid')); }
    else if (act === 'quick-genre') { state.filterGenre = el.getAttribute('data-genre'); navigate('#/katalog'); }
    else if (act === 'toggle-ch-sort') { state.chapterSortAsc = !state.chapterSortAsc; render(); }
    else if (act === 'toggle-reader-mode') { state.readerMode = state.readerMode === 'vertical' ? 'paged' : 'vertical'; render(); }
    else if (act === 'prev-page') { state.currentPageIdx = Math.max(0, state.currentPageIdx - 1); render(); }
    else if (act === 'next-page') { var max = Number(el.getAttribute('data-max')) - 1; state.currentPageIdx = Math.min(max, state.currentPageIdx + 1); render(); }
    else if (act === 'toggle-bookmark') {
      var id = el.getAttribute('data-id');
      var i = state.bookmarks.indexOf(id);
      if (i === -1) state.bookmarks.push(id); else state.bookmarks.splice(i, 1);
      localStorage.setItem('kv_bookmarks', JSON.stringify(state.bookmarks));
      render();
    }
    else if (act === 'retry-api') { state.error = null; syncFromApi(); }
    else if (act === 'share-manga') {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(window.location.href).catch(function () {});
      }
      var prevLabel = el.textContent;
      el.textContent = 'Tautan Disalin';
      setTimeout(function () { el.textContent = prevLabel; }, 2000);
    }
    else if (act === 'logout-user' || act === 'logout-admin') {
      state.user = null;
      state.adminToken = '';
      sessionStorage.removeItem('kv_session_token');
      render();
      syncFromApi();
    }
    /* --- Aksi panel admin --- */
    else if (act === 'admin-tab') { state.adminTab = el.getAttribute('data-tab'); state.adminForm = null; state.adminChapterForm = null; if (state.adminTab === 'pengguna') state.usersCache = undefined; render(); }
    else if (act === 'admin-delete-user') { deleteUserAdmin(el.getAttribute('data-id')); }
    else if (act === 'admin-new-manga') { state.adminForm = blankManga(); state.adminTab = 'manga'; render(); }
    else if (act === 'admin-edit-manga') {
      var am = mangaById(el.getAttribute('data-id'));
      if (am) { state.adminForm = JSON.parse(JSON.stringify(am)); state.adminForm.genresText = (am.genres || []).join(', '); state.adminTab = 'manga'; render(); }
    }
    else if (act === 'admin-cancel-form') { state.adminForm = null; state.adminChapterForm = null; render(); }
    else if (act === 'admin-preview-manga') { navigate('#/manga/' + el.getAttribute('data-slug')); }
    else if (act === 'admin-delete-manga') {
      var dm = mangaById(el.getAttribute('data-id'));
      if (dm) confirmDelete('manga', dm.id, 'Hapus manga "' + dm.title + '" beserta seluruh chapter dan komentarnya?', 'Hapus Manga');
    }
    else if (act === 'admin-new-chapter') {
      if (el.getAttribute('data-id')) state.adminChapterMangaId = el.getAttribute('data-id');
      if (!state.data.manga.length) { toast('Tambahkan manga terlebih dahulu di tab Manga.', 'warn'); }
      else { state.adminChapterForm = blankChapter(state.adminChapterMangaId); state.adminTab = 'chapter'; render(); }
    }
    else if (act === 'admin-toggle-expand') {
      var expId = el.getAttribute('data-id');
      state.adminExpandedManga = state.adminExpandedManga === expId ? null : expId;
      render();
    }
    else if (act === 'admin-open-chapters') {
      state.adminChapterMangaId = el.getAttribute('data-id');
      state.adminChapterForm = null;
      state.adminTab = 'chapter';
      render();
    }
    else if (act === 'admin-edit-chapter') {
      var ec = chapterById(el.getAttribute('data-id'));
      if (ec) {
        state.adminChapterForm = JSON.parse(JSON.stringify(ec));
        state.adminChapterForm.pages = state.adminChapterForm.pages || [];
        state.adminChapterMangaId = ec.mangaId;
        state.adminTab = 'chapter';
        render();
      }
    }
    else if (act === 'admin-move-chapter') { moveChapter(el.getAttribute('data-mid'), el.getAttribute('data-id'), el.getAttribute('data-dir')); }
    else if (act === 'admin-preview-chapter') { navigate('#/baca/' + el.getAttribute('data-slug') + '/' + el.getAttribute('data-cid')); }
    else if (act === 'admin-delete-chapter') {
      var dc = chapterById(el.getAttribute('data-id'));
      if (dc) confirmDelete('chapter', dc.id, 'Hapus Chapter ' + dc.number + ' ("' + (dc.title || 'tanpa judul') + '") beserta semua halamannya?', 'Hapus Chapter');
    }
    else if (act === 'admin-page-move') { movePage(Number(el.getAttribute('data-idx')), el.getAttribute('data-dir')); }
    else if (act === 'admin-page-remove') { removePage(Number(el.getAttribute('data-idx'))); }
    else if (act === 'admin-set-comment') { setCommentStatus(el.getAttribute('data-id'), el.getAttribute('data-status')); }
    else if (act === 'admin-delete-comment') {
      var cm = state.data.comments.filter(function (x) { return x.id === el.getAttribute('data-id'); })[0];
      if (cm) confirmDelete('comment', cm.id, 'Hapus komentar dari ' + cm.authorName + '?', 'Hapus Komentar');
    }
    else if (act === 'admin-reset-data') { confirmDelete('reset', '', 'Semua manga, chapter, dan komentar lokal akan dikembalikan ke data contoh.', 'Reset Data'); }
    else if (act === 'confirm-delete') { performConfirmedDelete(); }
    else if (act === 'cancel-delete') { state.pendingDelete = null; render(); }
  });

  // Aksesibilitas: elemen interaktif custom (kartu/baris) dapat diaktifkan via Enter/Spasi
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var t = e.target;
    if (!t || !t.getAttribute) return;
    if (['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].indexOf(t.tagName) !== -1) return;
    if (!t.hasAttribute('data-action')) return;
    e.preventDefault();
    t.click();
  });

  window.addEventListener('scroll', function () {
    var bar = document.getElementById('kv-progress-bar');
    if (!bar) return;
    var doc = document.documentElement;
    var pct = Math.min(100, Math.round((doc.scrollTop / Math.max(1, doc.scrollHeight - doc.clientHeight)) * 100));
    bar.style.width = pct + '%';
  });

  function handleRouteChange() {
    state.mobileMenuOpen = false;
    state.commentNotice = null;
    parseRoute();
    render();
    window.scrollTo(0, 0);
  }

  window.addEventListener('popstate', handleRouteChange);
  window.addEventListener('hashchange', handleRouteChange);

  applyTheme();
  parseRoute();
  initializeAuth();
})();
//
